'use client';

import { useState } from 'react';
import type { ThemeConfig, MeasureMode, UnitSystem, Entry, RoofComponentDef, PitchType, CustomComponentDef, TakeoffCapabilities } from '@roof-takeoff/core';
import { COMPONENT_DEFS, areaValueForUnit, computeEntry, makeId, makeCustomId, registerCustomKind, componentLabel, componentDescription } from '@roof-takeoff/core';

// ─── Info Icon (hover + click tooltip) ───────────────

export function InfoIcon({ text, color = '#94a3b8' }: { text: string; color?: string }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="relative inline-flex" onMouseLeave={() => setOpen(false)}>
      <button
        type="button"
        onClick={() => setOpen(o => !o)}
        onMouseEnter={() => setOpen(true)}
        className="text-slate-300 hover:text-slate-500 transition rounded-full p-0.5 cursor-pointer"
        aria-label="More info"
      >
        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      </button>
      {open && (
        <div className="absolute z-50 top-full left-1/2 -translate-x-1/2 mt-1 w-64 rounded-lg bg-slate-900 text-white text-xs p-3 shadow-lg" style={{ borderColor: color }}>
          {text}
          <div className="absolute -top-1 left-1/2 -translate-x-1/2 w-2 h-2 bg-slate-900 rotate-45" />
        </div>
      )}
    </div>
  );
}

// ─── Component symbols (SVG) ─────────────────────────

export function ComponentSymbol({ kind, customDef, className = 'w-4 h-4', color }: { kind: string; customDef?: CustomComponentDef; className?: string; color?: string }) {
  const stroke = color || 'currentColor';
  const sw = 1.8;
  switch (kind) {
    case 'roof_area':
      return (
        <svg className={className} fill="none" viewBox="0 0 24 24" stroke={stroke} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M3 12l9-9 9 9M5 10v10h14V10" />
        </svg>
      );
    case 'ridge':
      return (
        <svg className={className} fill="none" viewBox="0 0 24 24" stroke={stroke} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M4 20L12 6l8 14" />
        </svg>
      );
    case 'hip':
      return (
        <svg className={className} fill="none" viewBox="0 0 24 24" stroke={stroke} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M4 20L12 6l8 14" />
        </svg>
      );
    case 'valley':
      return (
        <svg className={className} fill="none" viewBox="0 0 24 24" stroke={stroke} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M4 6l8 14 8-14" />
        </svg>
      );
    case 'barge':
      return (
        <svg className={className} fill="none" viewBox="0 0 24 24" stroke={stroke} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M5 20V4h14" />
        </svg>
      );
    case 'spouting':
      return (
        <svg className={className} fill="none" viewBox="0 0 24 24" stroke={stroke} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M4 8v3a2 2 0 002 2h12a2 2 0 002-2V8" />
        </svg>
      );
    case 'underlay':
      return (
        <svg className={className} fill="none" viewBox="0 0 24 24" stroke={stroke} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M3 8l9-5 9 5-9 5-9-5z" />
          <path strokeLinecap="round" strokeLinejoin="round" d="M3 12l9 5 9-5" />
          <path strokeLinecap="round" strokeLinejoin="round" d="M3 16l9 5 9-5" />
        </svg>
      );
    case 'fixings':
      return (
        <svg className={className} fill="none" viewBox="0 0 24 24" stroke={stroke} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M8 4h8M12 4v16M9 20l3-2 3 2" />
        </svg>
      );
    default:
      if (customDef?.measurementType === 'area') {
        return (
          <svg className={className} fill="none" viewBox="0 0 24 24" stroke={stroke} strokeWidth={sw}>
            <rect x="4" y="4" width="16" height="16" rx="2" />
            <path strokeLinecap="round" strokeLinejoin="round" d="M8 16l8-8M8 8h.01M16 16h.01" />
          </svg>
        );
      }
      return (
        <svg className={className} fill="none" viewBox="0 0 24 24" stroke={stroke} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M11.42 15.17L17.25 21A2.652 2.652 0 0021 17.25l-5.877-5.877M11.42 15.17l2.496-3.03c.317-.384.74-.626 1.208-.766M11.42 15.17l-4.655 5.653a2.548 2.548 0 11-3.586-3.586l6.837-5.63m5.108-.233c.55-.164 1.163-.188 1.743-.14a4.5 4.5 0 004.486-6.336l-3.276 3.277a3.004 3.004 0 01-2.25-2.25l3.276-3.276a4.5 4.5 0 00-6.336 4.486c.091 1.076-.071 2.264-.904 2.95l-.102.085m-1.745 1.437L5.909 7.5H4.5L2.25 3.75l1.5-1.5L7.5 4.5v1.409l4.26 4.26m-1.745 1.437l1.745-1.437m6.615 8.206L15.75 15.75M4.5 19.5h3m-3 0v-3" />
        </svg>
      );
  }
}

// ─── Add Entry Form ──────────────────────────────────

export function AddEntryForm({ theme, kind, customDef, measureMode, lenLabel, areaLabel, availableComponents, pitchDegrees, unitSystem, roofAreaTotal, onAdd, capabilities }: {
  theme: ThemeConfig;
  kind: string;
  customDef?: CustomComponentDef;
  measureMode: MeasureMode;
  lenLabel: string;
  areaLabel: string;
  availableComponents: RoofComponentDef[];
  pitchDegrees: number;
  unitSystem: UnitSystem;
  roofAreaTotal: number | null;
  onAdd: (entry: Entry) => void;
  capabilities?: TakeoffCapabilities;
}) {
  const pitchType = customDef?.pitchType ?? COMPONENT_DEFS[kind]?.pitchType ?? 'none';
  const isRoofArea = kind === 'roof_area' || kind === 'underlay' || kind === 'fixings' || (customDef?.measurementType === 'area');
  const isFixed = customDef?.measurementType === 'fixed';
  const usePitch = measureMode === 'plan' && pitchType !== 'none';
  const planPrefix = measureMode === 'plan' ? 'Plan ' : '';

  const [areaMode, setAreaMode] = useState<'dimensions' | 'total'>(isRoofArea ? 'dimensions' : 'total');
  const [val1, setVal1] = useState('');
  const [val2, setVal2] = useState('');
  const [totalVal, setTotalVal] = useState('');
  const [quantity, setQuantity] = useState('1');
  const [label, setLabel] = useState('');
  const [selectedComponentId, setSelectedComponentId] = useState<string | null>(availableComponents[0]?.id ?? null);
  const [pricingMode, setPricingMode] = useState<'component' | 'known_price'>('component');
  const [knownPrice, setKnownPrice] = useState('');
  const canUseKnownPrice = capabilities?.knownPriceEntries ?? false;

  const resetForm = () => { setVal1(''); setVal2(''); setTotalVal(''); setQuantity('1'); setLabel(''); setKnownPrice(''); setPricingMode('component'); };

  const handleAdd = () => {
    let entry: Entry;
    const qty = parseInt(quantity) || 1;
    const kp = (canUseKnownPrice && pricingMode === 'known_price') ? parseFloat(knownPrice) : undefined;
    const compId = (canUseKnownPrice && pricingMode === 'known_price') ? null : selectedComponentId;

    if (isFixed) {
      // Fixed: quantity-based, no dimensions or pitch
      entry = { id: makeId(), label, inputMode: 'actual', pitchDegrees: 0, actualValue: qty, computedValue: 0, selectedComponentId: compId, quantity: qty, isTotalInput: false, knownPrice: kp };
      entry.computedValue = computeEntry(entry, kind, pitchType);
      onAdd(entry);
      resetForm();
      return;
    }

    if (isRoofArea) {
      if (areaMode === 'dimensions') {
        const w = parseFloat(val1); const l = parseFloat(val2);
        if (!w || w <= 0 || !l || l <= 0) return;
        entry = { id: makeId(), label, inputMode: usePitch ? 'pitch_calculated' : 'actual', planWidth: w, planLengthVal: l, pitchDegrees, actualValue: usePitch ? 0 : w * l, computedValue: 0, selectedComponentId: compId, quantity: qty, isTotalInput: false, knownPrice: kp };
      } else {
        const t = parseFloat(totalVal); if (!t || t <= 0) return;
        entry = { id: makeId(), label, inputMode: usePitch ? 'pitch_calculated' : 'actual', pitchDegrees, actualValue: t, computedValue: 0, selectedComponentId: compId, quantity: qty, isTotalInput: true, knownPrice: kp };
      }
    } else {
      const l = parseFloat(val1); if (!l || l <= 0) return;
      entry = { id: makeId(), label, inputMode: usePitch ? 'pitch_calculated' : 'actual', planLength: l, pitchDegrees, actualValue: usePitch ? 0 : l, computedValue: 0, selectedComponentId: compId, quantity: qty, isTotalInput: false, knownPrice: kp };
    }

    entry.computedValue = computeEntry(entry, kind, pitchType);
    if (isRoofArea) entry.computedValue = areaValueForUnit(entry.computedValue, unitSystem, areaMode === 'dimensions');
    onAdd(entry);
    resetForm();
  };

  const canAdd = isFixed ? parseInt(quantity) > 0 : isRoofArea ? (areaMode === 'dimensions' ? (parseFloat(val1) > 0 && parseFloat(val2) > 0) : parseFloat(totalVal) > 0) : parseFloat(val1) > 0;
  const canAddWithPrice = canAdd && (pricingMode === 'component' || (pricingMode === 'known_price' && parseFloat(knownPrice) > 0));
  const inputCls = "w-full rounded-lg border border-slate-300 px-3 py-2.5 text-base focus:outline-none";
  const cur = theme.currencySymbol;

  return (
    <div className="rounded-xl border border-slate-200 bg-slate-50/50 p-4 space-y-3">
      {isRoofArea && (
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1 rounded-full border border-slate-200 bg-white p-0.5 w-fit">
            <button onClick={() => setAreaMode('dimensions')} className="cursor-pointer rounded-full px-3 py-1 text-xs font-medium transition" style={areaMode === 'dimensions' ? { backgroundColor: theme.primary, color: '#fff' } : { color: '#64748b' }}>Width x Length</button>
            <button onClick={() => setAreaMode('total')} className="cursor-pointer rounded-full px-3 py-1 text-xs font-medium transition" style={areaMode === 'total' ? { backgroundColor: theme.primary, color: '#fff' } : { color: '#64748b' }}>Total Area</button>
          </div>
        </div>
      )}

      {isRoofArea && kind !== 'roof_area' && roofAreaTotal !== null && roofAreaTotal > 0 && (
        <div className="flex items-center gap-1.5">
          <button onClick={() => { setAreaMode('total'); setTotalVal(roofAreaTotal.toFixed(2)); }} className="cursor-pointer rounded-lg px-3 py-1.5 text-xs font-medium text-white transition" style={{ backgroundColor: theme.primary }}>Use Roof Area ({roofAreaTotal.toFixed(2)} {areaLabel})</button>
          <div className="relative group flex-shrink-0">
            <span className="cursor-help inline-flex items-center justify-center w-4 h-4 rounded-full border border-slate-300 text-slate-400 text-[10px] font-bold">?</span>
            <div className="absolute left-1/2 -translate-x-1/2 bottom-full mb-1.5 w-48 rounded-lg bg-slate-800 text-white text-xs px-3 py-2 opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-10">This automatically applies the total roof area you added in step 1</div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-2 gap-3">
        {isFixed ? (
          <div className="col-span-2"><label className="text-xs font-medium text-slate-600">Quantity</label><input type="number" value={quantity} onChange={(e) => setQuantity(e.target.value)} min={1} step={1} inputMode="numeric" placeholder="1" className={inputCls} /></div>
        ) : isRoofArea && areaMode === 'dimensions' ? (
          <>
            <div><label className="text-xs font-medium text-slate-600">{planPrefix}Width ({lenLabel})</label><input type="number" value={val1} onChange={(e) => setVal1(e.target.value)} min={0} step="any" inputMode="decimal" placeholder="0" className={inputCls} style={{ borderColor: theme.primary }} /></div>
            <div><label className="text-xs font-medium text-slate-600">{planPrefix}Length ({lenLabel})</label><input type="number" value={val2} onChange={(e) => setVal2(e.target.value)} min={0} step="any" inputMode="decimal" placeholder="0" className={inputCls} style={{ borderColor: theme.primary }} /></div>
          </>
        ) : isRoofArea && areaMode === 'total' ? (
          <div className="col-span-2"><label className="text-xs font-medium text-slate-600">{planPrefix}Area ({areaLabel})</label><input type="number" value={totalVal} onChange={(e) => setTotalVal(e.target.value)} min={0} step="any" inputMode="decimal" placeholder="0" className={inputCls} style={{ borderColor: theme.primary }} /></div>
        ) : (
          <div className="col-span-2"><label className="text-xs font-medium text-slate-600">{planPrefix}Length ({lenLabel})</label><input type="number" value={val1} onChange={(e) => setVal1(e.target.value)} min={0} step="any" inputMode="decimal" placeholder="0" className={inputCls} style={{ borderColor: theme.primary }} /></div>
        )}
      </div>

      {/* Pricing mode toggle: component vs known price */}
      {canUseKnownPrice && availableComponents.length > 0 && (
        <div className="flex items-center gap-1 rounded-full border border-slate-200 bg-white p-0.5 w-fit">
          <button onClick={() => setPricingMode('component')} className="cursor-pointer rounded-full px-3 py-1 text-xs font-medium transition" style={pricingMode === 'component' ? { backgroundColor: theme.primary, color: '#fff' } : { color: '#64748b' }}>Select Product</button>
          <button onClick={() => setPricingMode('known_price')} className="cursor-pointer rounded-full px-3 py-1 text-xs font-medium transition" style={pricingMode === 'known_price' ? { backgroundColor: theme.primary, color: '#fff' } : { color: '#64748b' }}>Known Price</button>
        </div>
      )}

      {pricingMode === 'component' && availableComponents.length > 0 && (
        <div>
          <label className="text-xs font-medium text-slate-600">Product</label>
          <select value={selectedComponentId || ''} onChange={(e) => setSelectedComponentId(e.target.value || null)} className="mt-0.5 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-700 focus:outline-none cursor-pointer" style={{ borderColor: theme.primary }}>
            <option value="">- No product (measurements only) -</option>
            {availableComponents.map(comp => (<option key={comp.id} value={comp.id}>{comp.name} ({cur}{comp.price_per_unit.toFixed(2)}/{comp.unit})</option>))}
          </select>
        </div>
      )}
      {canUseKnownPrice && pricingMode === 'known_price' && (
        <div>
          <label className="text-xs font-medium text-slate-600">Price per {isFixed ? 'piece' : isRoofArea ? areaLabel : lenLabel}</label>
          <input type="number" value={knownPrice} onChange={(e) => setKnownPrice(e.target.value)} min={0} step="any" inputMode="decimal" placeholder="0.00" className={inputCls} style={{ borderColor: theme.primary }} />
        </div>
      )}

      <input type="text" value={label} onChange={(e) => setLabel(e.target.value)} placeholder="Optional label (e.g. Front gable, Main roof)" className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm text-slate-600 focus:outline-none" />

      <div className="grid grid-cols-2 gap-3">
        <div><label className="text-xs font-medium text-slate-600">Quantity</label><input type="number" value={quantity} onChange={(e) => setQuantity(e.target.value)} min={1} step={1} inputMode="numeric" className={inputCls} /></div>
        <div className="flex items-end">
          <button onClick={handleAdd} disabled={!canAddWithPrice} className="w-full cursor-pointer rounded-lg px-4 py-2.5 text-sm font-semibold text-white transition min-h-[44px]" style={canAddWithPrice ? { backgroundColor: theme.primary } : { backgroundColor: '#e2e8f0', color: '#94a3b8', cursor: 'not-allowed' }}>Add Entry</button>
        </div>
      </div>
    </div>
  );
}

// ─── Entry List Item ─────────────────────────────────

export function EntryListItem({ entry, index, kind, customDef, measureMode, lenLabel, areaLabel, wastePercent, onRemove }: {
  entry: Entry;
  index: number;
  kind: string;
  customDef?: CustomComponentDef;
  measureMode: MeasureMode;
  lenLabel: string;
  areaLabel: string;
  wastePercent: number;
  onRemove: () => void;
}) {
  const isRoofArea = kind === 'roof_area' || kind === 'underlay' || kind === 'fixings' || (customDef?.measurementType === 'area');
  const isFixed = customDef?.measurementType === 'fixed';
  const unit = isFixed ? 'pcs' : isRoofArea ? areaLabel : lenLabel;
  const usePitch = measureMode === 'plan' && entry.inputMode === 'pitch_calculated';
  const inputDesc = isFixed ? `Qty: ${entry.quantity ?? 1}` : entry.isTotalInput ? `Total: ${entry.actualValue ?? 0}` : isRoofArea ? `${entry.planWidth ?? 0} x ${entry.planLengthVal ?? 0}` : `${entry.planLength ?? entry.actualValue ?? 0}`;

  return (
    <div className="flex items-center justify-between rounded-xl border border-slate-200 bg-white px-4 py-3 transition hover:border-slate-300">
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <span className="text-sm font-medium text-slate-700">{entry.label || `Entry ${index + 1}`}</span>
          {usePitch && <span className="text-xs text-slate-400">@ {entry.pitchDegrees} deg</span>}
          {entry.quantity && entry.quantity > 1 && <span className="text-xs text-slate-400">x{entry.quantity}</span>}
        </div>
        <div className="flex items-center gap-2 mt-0.5 flex-wrap">
          <span className="text-xs text-slate-400">{inputDesc}</span>
          {usePitch && <span className="text-xs text-slate-300">-&gt;</span>}
          <span className="text-xs text-slate-500">{entry.computedValue.toFixed(2)} {unit}</span>
          {wastePercent > 0 && <span className="text-xs text-slate-400">+{wastePercent}% = {(entry.computedValue * (1 + wastePercent / 100)).toFixed(2)}</span>}
        </div>
        {entry.knownPrice != null && entry.knownPrice > 0 && (
          <div className="mt-0.5"><span className="text-xs text-slate-500">Known price</span> <span className="text-xs font-medium" style={{ color: '#BD4A1A' }}>{entry.knownPrice.toFixed(2)}/{isFixed ? 'pc' : isRoofArea ? areaLabel : lenLabel}</span></div>
        )}
      </div>
      <button onClick={onRemove} className="text-slate-300 hover:text-red-500 transition p-1 cursor-pointer" aria-label="Remove entry">
        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
      </button>
    </div>
  );
}

// ─── Custom Component Creator ────────────────────────

export function CustomComponentCreator({ theme, onCreate }: {
  theme: ThemeConfig;
  onCreate: (def: CustomComponentDef) => void;
}) {
  const [open, setOpen] = useState(false);
  const [name, setName] = useState('');
  const [measurementType, setMeasurementType] = useState<'linear' | 'area' | 'fixed'>('linear');
  const [pitchType, setPitchType] = useState<PitchType>('none');
  const [waste, setWaste] = useState('5');

  const handleCreate = () => {
    if (!name.trim()) return;
    const def: CustomComponentDef = {
      id: makeCustomId(),
      name: name.trim(),
      measurementType,
      pitchType: measurementType === 'fixed' ? 'none' : pitchType,
      wastePercent: parseFloat(waste) || 5,
    };
    registerCustomKind(def.id, measurementType === 'area', measurementType === 'fixed');
    onCreate(def);
    setName('');
    setMeasurementType('linear');
    setPitchType('none');
    setWaste('5');
    setOpen(false);
  };

  if (!open) {
    return (
      <button onClick={() => setOpen(true)} className="w-full rounded-xl border border-dashed border-slate-300 px-4 py-3 text-sm text-slate-500 hover:bg-slate-50 transition cursor-pointer">
        + Add Custom Component
      </button>
    );
  }

  return (
    <div className="rounded-xl border border-slate-200 bg-slate-50/50 p-4 space-y-3">
      <div className="flex items-center justify-between">
        <h4 className="text-sm font-semibold text-slate-900">Add Custom Component</h4>
        <button onClick={() => setOpen(false)} className="text-slate-400 hover:text-slate-600 cursor-pointer">
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
        </button>
      </div>
      <div>
        <label className="text-xs font-medium text-slate-600">Name</label>
        <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Skylight flashing" className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm focus:outline-none mt-0.5" style={{ borderColor: name ? theme.primary : undefined }} />
      </div>
      <div className="grid grid-cols-3 gap-2">
        <div>
          <label className="text-xs font-medium text-slate-600">Type</label>
          <select value={measurementType} onChange={(e) => setMeasurementType(e.target.value as 'linear' | 'area' | 'fixed')} className="w-full rounded-lg border border-slate-300 px-2 py-1.5 text-sm focus:outline-none mt-0.5 cursor-pointer">
            <option value="linear">Linear</option>
            <option value="area">Area</option>
            <option value="fixed">Fixed</option>
          </select>
        </div>
        <div>
          <label className="text-xs font-medium text-slate-600">Pitch</label>
          <select value={measurementType === 'fixed' ? 'none' : pitchType} onChange={(e) => setPitchType(e.target.value as PitchType)} disabled={measurementType === 'fixed'} className="w-full rounded-lg border border-slate-300 px-2 py-1.5 text-sm focus:outline-none mt-0.5 cursor-pointer">
            <option value="none">None</option>
            <option value="rafter">Rafter</option>
            <option value="hip_valley">Hip/Valley</option>
          </select>
        </div>
        <div>
          <label className="text-xs font-medium text-slate-600">Waste %</label>
          <input type="number" value={measurementType === 'fixed' ? '0' : waste} onChange={(e) => setWaste(e.target.value)} min={0} max={100} step={1} disabled={measurementType === 'fixed'} className="w-full rounded-lg border border-slate-300 px-2 py-1.5 text-sm focus:outline-none mt-0.5" />
        </div>
      </div>
      {measurementType === 'fixed' && (
        <p className="text-xs text-slate-400">Fixed components are priced per piece. Enter the quantity when adding entries.</p>
      )}
      <button onClick={handleCreate} disabled={!name.trim()} className="w-full rounded-lg px-4 py-2 text-sm font-semibold text-white transition cursor-pointer disabled:opacity-50" style={{ backgroundColor: theme.primary }}>
        Add Component
      </button>
    </div>
  );
}
