'use client';

import { useState, useMemo, useCallback, useEffect, type CSSProperties } from 'react';
import Link from 'next/link';
import type {
  ThemeConfig,
  MeasureMode,
  UnitSystem,
  Entry,
  ComponentSection,
  RoofComponentDef,
  PitchType,
  CustomComponentDef,
  PricingMode,
  LayoutChoice,
  TakeoffCapabilities,
  TakeoffPrefill,
} from '@roof-takeoff/core';
import {
  COMPONENT_DEFS,
  BUILT_IN_ORDER,
  areaValueForUnit,
  entriesFromPrefillValues,
  computeEntry,
  makeInitialSections,
  makeCustomSection,
  makeCustomId,
  registerCustomKind,
  calculateTakeoffSections,
  unitLabel,
  areaUnitLabel,
  ratioToDegrees,
  degreesToRatio,
  componentLabel,
  componentDescription,
} from '@roof-takeoff/core';
import { ResultsModal } from '@roof-takeoff/ui';
import { InfoIcon, ComponentSymbol, AddEntryForm, EntryListItem, CustomComponentCreator } from './components';

interface ClassicLayoutProps {
  theme: ThemeConfig;
  components: RoofComponentDef[];
  initialMeasureMode?: MeasureMode | null;
  pricingMode?: PricingMode | null;
  capabilities?: TakeoffCapabilities;
  prefill?: TakeoffPrefill | null;
  onSwitchLayout?: (choice: LayoutChoice) => void;
}

export function ClassicLayout({ theme, components, initialMeasureMode = null, pricingMode = null, capabilities, prefill = null, onSwitchLayout }: ClassicLayoutProps) {
  const [measureMode, setMeasureMode] = useState<MeasureMode | null>(prefill?.measureMode ?? initialMeasureMode);
  const [step, setStep] = useState(0);
  const [masterPitch, setMasterPitch] = useState('25');
  const [masterRatio, setMasterRatio] = useState('5:12');
  const [pitchMode, setPitchMode] = useState<'degrees' | 'ratio'>('degrees');
  const [sections, setSections] = useState<Record<string, ComponentSection>>(makeInitialSections);
  const [customSections, setCustomSections] = useState<Record<string, ComponentSection>>({});
  const [expandedSection, setExpandedSection] = useState<string | null>('roof_area');
  const [showResults, setShowResults] = useState(false);
  const [prefillApplied, setPrefillApplied] = useState(!prefill);

  const u = theme.defaultUnits;
  const lenLbl = unitLabel(u);
  const areaLbl = areaUnitLabel(u);
  const cur = theme.currencySymbol;

  const componentsByKind = useMemo(() => {
    const map: Record<string, RoofComponentDef[]> = {};
    for (const kind of BUILT_IN_ORDER) {
      map[kind] = components.filter(c => c.component_kind === kind);
    }
    return map;
  }, [components]);

  const getComponentById = useCallback((id: string | null): RoofComponentDef | null => {
    if (!id) return null;
    return components.find(c => c.id === id) ?? null;
  }, [components]);

  const effectivePitch = parseFloat(masterPitch) || 0;

  useEffect(() => {
    if (measureMode !== 'plan') return;
    const recalculate = (current: Record<string, ComponentSection>) => {
      let changed = false;
      const next: Record<string, ComponentSection> = {};
      for (const [key, section] of Object.entries(current)) {
        const pitchType = section.customDef?.pitchType ?? COMPONENT_DEFS[key]?.pitchType ?? 'none';
        const isArea = key === 'roof_area' || key === 'underlay' || key === 'fixings' || section.customDef?.measurementType === 'area';
        const entries = section.entries.map(entry => {
          if (entry.inputMode !== 'pitch_calculated') return entry;
          const updated = { ...entry, pitchDegrees: effectivePitch };
          let cv = computeEntry(updated, key, pitchType);
          if (isArea) cv = areaValueForUnit(cv, u, !entry.isTotalInput);
          changed = changed || cv !== entry.computedValue || entry.pitchDegrees !== effectivePitch;
          return { ...updated, computedValue: cv };
        });
        next[key] = { ...section, entries };
      }
      return changed ? next : current;
    };
    setSections(recalculate);
    setCustomSections(recalculate);
  }, [effectivePitch, measureMode, u]);

  const allSections = useMemo(() => ({ ...sections, ...customSections }), [sections, customSections]);
  const allKeys = useMemo(() => [...BUILT_IN_ORDER, ...Object.keys(customSections)], [customSections]);

  const showLabour = pricingMode !== 'material';

  const calculation = useMemo(
    () => calculateTakeoffSections(allSections, allKeys, getComponentById, showLabour),
    [allSections, allKeys, getComponentById, showLabour],
  );
  const totals = calculation.sections;
  const hasData = calculation.totalEntries > 0;
  const grandTotal = showLabour ? calculation.grandTotal : calculation.materialTotal;

  const addEntry = (key: string, entry: Entry) => {
    const setter = key.startsWith('custom-') ? setCustomSections : setSections;
    setter(prev => ({ ...prev, [key]: { ...prev[key], entries: [...prev[key].entries, entry] } }));
  };
  const removeEntry = (key: string, entryId: string) => {
    const setter = key.startsWith('custom-') ? setCustomSections : setSections;
    setter(prev => ({ ...prev, [key]: { ...prev[key], entries: prev[key].entries.filter(e => e.id !== entryId) } }));
  };
  const updateWaste = (key: string, waste: number) => {
    const setter = key.startsWith('custom-') ? setCustomSections : setSections;
    setter(prev => ({ ...prev, [key]: { ...prev[key], wastePercent: waste } }));
  };

  const addCustomComponent = (def: CustomComponentDef) => {
    const key = `custom-${def.id}`;
    const section = makeCustomSection(def);
    setCustomSections(prev => ({ ...prev, [key]: section }));
    setExpandedSection(key);
  };

  const removeCustomComponent = (key: string) => {
    setCustomSections(prev => {
      const next = { ...prev };
      delete next[key];
      return next;
    });
  };

  const startOver = () => {
    setSections(makeInitialSections());
    setCustomSections({});
    setMasterPitch('25');
    setMasterRatio('5:12');
    setExpandedSection('roof_area');
    setMeasureMode(null);
    setStep(0);
    setShowResults(false);
  };

  const updatePitchDegrees = (val: string) => {
    setMasterPitch(val);
    const deg = parseFloat(val) || 0;
    setMasterRatio(degreesToRatio(deg, u));
  };

  // Apply prefilled measurements once on mount (AI-agent / shared-link flow)
  useEffect(() => {
    if (!prefill || prefillApplied) return;
    const pitch = prefill.pitchDegrees;
    if (typeof pitch === 'number' && pitch > 0 && Number.isFinite(pitch)) {
      setMasterPitch(String(pitch));
      setMasterRatio(degreesToRatio(pitch, u));
    }
    if (prefill.wastePercent) {
      setSections(prev => {
        const next = { ...prev };
        for (const [k, w] of Object.entries(prefill.wastePercent!)) {
          if (next[k]) next[k] = { ...next[k], wastePercent: w };
        }
        return next;
      });
    }
    setSections(prev => {
      const next = { ...prev };
      const entriesByKind = entriesFromPrefillValues(prefill.values, prefill.measureMode, typeof pitch === 'number' ? pitch : parseFloat(masterPitch) || 0, u);
      for (const [k, entries] of Object.entries(entriesByKind)) {
        if (next[k]) next[k] = { ...next[k], entries };
      }
      return next;
    });
    setPrefillApplied(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [prefill, prefillApplied]);
  const updatePitchRatio = (val: string) => {
    setMasterRatio(val);
    const deg = ratioToDegrees(val);
    if (deg > 0) setMasterPitch(deg.toFixed(1));
  };

  // Compute pre-pitch roof area for "Use Roof Area" button on underlay/fixings
  const roofAreaPrePitch = useMemo(() => {
    const section = allSections['roof_area'];
    if (!section || section.entries.length === 0) return null;
    let total = 0;
    for (const entry of section.entries) {
      const qty = entry.quantity ?? 1;
      if (entry.inputMode === 'actual') {
        total += (entry.actualValue ?? 0) * qty;
      } else if (entry.isTotalInput) {
        total += (entry.actualValue ?? 0) * qty;
      } else {
        total += ((entry.planWidth ?? 0) * (entry.planLengthVal ?? 0)) * qty;
      }
    }
    return total > 0 ? total : null;
  }, [allSections]);

  const roofAreaTotal = roofAreaPrePitch;

  const renderSection = (key: string) => {
    const section = allSections[key];
    if (!section) return null;
    const isCustom = key.startsWith('custom-');
    const label = componentLabel(key, section.customDef);
    const desc = componentDescription(key, section.customDef);
    const isRoofArea = key === 'roof_area' || key === 'underlay' || key === 'fixings';
    const isExpanded = expandedSection === key;
    const total = totals[key] ?? { rawTotal: 0, withWaste: 0, count: 0, totalCost: 0 };
    const hasEntries = section.entries.length > 0;
    const isFixedSection = isCustom && section.customDef?.measurementType === 'fixed';
    const displayUnit = isFixedSection ? 'pcs' : isRoofArea || (isCustom && section.customDef?.measurementType === 'area') ? areaLbl : lenLbl;
    const availableComponents = isCustom ? components : (componentsByKind[key] || []);

    return (
      <div key={key} className={`rounded-xl border bg-white transition ${isExpanded ? 'border-slate-300 shadow-sm' : 'border-slate-200'}`}>
        <div className="flex items-center justify-between px-2 md:px-4 py-3">
          <button onClick={() => setExpandedSection(isExpanded ? null : key)} className="flex items-center gap-2.5 cursor-pointer transition flex-1 min-w-0" style={{ color: isExpanded ? theme.primary : undefined }}>
            <ComponentSymbol kind={key} customDef={section.customDef} className="w-4 h-4 text-slate-500 flex-shrink-0" />
            <span className="text-sm font-semibold text-slate-900 truncate">{label}</span>
            {hasEntries && <span className="rounded-full bg-slate-100 px-2 py-0.5 text-xs text-slate-500 flex-shrink-0">{section.entries.length} {section.entries.length === 1 ? 'entry' : 'entries'}</span>}
            {!hasEntries && <span className="text-xs text-slate-400 truncate hidden md:inline">{desc}</span>}
          </button>
          <div className="mr-2 flex-shrink-0"><InfoIcon text={desc} color={theme.primary} /></div>
          <div className="flex items-center gap-3 flex-shrink-0">
            {hasEntries && (
              <div className="text-right">
                <span className="text-sm font-semibold text-slate-900">{total.rawTotal.toFixed(2)} {displayUnit}</span>
                {total.totalCost > 0 && <span className="ml-2 text-xs font-medium" style={{ color: theme.primary }}>{cur}{total.totalCost.toFixed(2)}</span>}
                {section.wastePercent > 0 && <span className="ml-2 text-xs text-slate-400">+{section.wastePercent}%</span>}
              </div>
            )}
            {isCustom && (
              <button onClick={() => removeCustomComponent(key)} className="text-slate-300 hover:text-red-500 transition p-1 cursor-pointer" aria-label="Remove custom component">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            )}
            <button onClick={() => setExpandedSection(isExpanded ? null : key)}>
              <svg className={`w-4 h-4 text-slate-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
              </svg>
            </button>
          </div>
        </div>
        {isExpanded && (
          <div className="border-t border-slate-100 p-2 md:p-4 space-y-3">
            <div className="flex items-center gap-2">
              <label htmlFor={`${key}-waste`} className="text-xs font-medium text-slate-600">Waste</label>
              <InfoIcon text="Waste percentage is added to the raw quantity at the end. The raw total shown does NOT include waste - the final total with waste is shown in the results." color={theme.primary} />
              <div className="relative">
                <input id={`${key}-waste`} name={`${key}WastePercent`} type="number" value={section.wastePercent} onChange={(e) => updateWaste(key, parseFloat(e.target.value) || 0)} min={0} max={100} step={1} className="w-16 rounded-lg border border-slate-300 px-2 py-1 text-base md:text-sm text-center focus:outline-none" style={{ borderColor: theme.primary }} />
                <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-slate-400">%</span>
              </div>
            </div>

            <AddEntryForm theme={theme} kind={key} customDef={section.customDef} measureMode={measureMode!} lenLabel={lenLbl} areaLabel={areaLbl} availableComponents={availableComponents} pitchDegrees={effectivePitch} unitSystem={u} roofAreaTotal={isRoofArea && key !== 'roof_area' ? roofAreaTotal : null} onAdd={(entry) => addEntry(key, entry)} capabilities={capabilities} />

            {hasEntries && (
              <div className="space-y-1.5">
                {section.entries.map((entry, idx) => (
                  <EntryListItem key={entry.id} entry={entry} index={idx} kind={key} customDef={section.customDef} measureMode={measureMode!} lenLabel={lenLbl} areaLabel={areaLbl} wastePercent={section.wastePercent} onRemove={() => removeEntry(key, entry.id)} />
                ))}
              </div>
            )}

            {!hasEntries && <p className="text-xs text-slate-400 text-center py-2">No {label.toLowerCase()} entries yet. Add your first one above.</p>}
          </div>
        )}
      </div>
    );
  };

  const planStep = measureMode === 'plan';
  const stepLabels = planStep ? ['Pitch', 'Roof Area', 'Components', 'Generate'] : ['Roof Area', 'Components', 'Generate'];

  return (
    <main
      className="roof-takeoff-theme min-h-screen bg-white flex flex-col"
      style={{ fontFamily: theme.bodyFont, '--roof-heading-font': theme.headingFont } as CSSProperties}
    >
      <header className="border-b border-slate-100 sticky top-0 z-10 bg-white/95 backdrop-blur-sm">
        <div className="mx-auto max-w-5xl px-2 md:px-6 py-3 flex items-center justify-between">
          <Link href="/" className="flex items-center">
            {theme.logoUrl ? (
              <img src={theme.logoUrl} alt={theme.supplierName ?? undefined} className="h-8 md:h-10 w-auto" />
            ) : (
              <span className="text-sm font-semibold text-slate-900">{theme.copy.headerTitle}</span>
            )}
          </Link>
          <div className="flex items-center gap-3">
            {onSwitchLayout && (
              <button onClick={() => onSwitchLayout('guided')} className="cursor-pointer rounded-full border border-slate-200 px-3 py-1 text-xs font-medium text-slate-500 hover:text-slate-700 hover:border-slate-300 transition">
                Guided mode
              </button>
            )}
            {theme.copy.poweredBy && (
              <span className="text-xs text-slate-400">{theme.copy.poweredBy}</span>
            )}
          </div>
        </div>
      </header>

      <div className="flex-1 mx-auto w-full max-w-5xl px-2 md:px-6 py-6 md:py-10 pb-24 md:pb-10">
        {/* Step 1: Measurement Mode */}
        {!measureMode && (
          <div className="space-y-4">
            <div className="text-center">
              <h2 className="text-lg font-semibold text-slate-900">How do you want to enter your measurements?</h2>
              <p className="mt-1 text-sm text-slate-500">Choose the method that matches your measurements.</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-6">
              <button onClick={() => setMeasureMode('actual')}
                className="group w-full rounded-2xl border-2 border-slate-200 bg-white p-6 text-left transition-all cursor-pointer hover:shadow-lg min-h-[180px] flex flex-col"
                onMouseEnter={(e) => { e.currentTarget.style.borderColor = theme.primary; e.currentTarget.style.boxShadow = `0 4px 20px ${theme.primary}15`; }}
                onMouseLeave={(e) => { e.currentTarget.style.borderColor = ''; e.currentTarget.style.boxShadow = ''; }}>
                <div className="flex items-start mb-3">
                  <div className="w-12 h-12 rounded-full flex items-center justify-center" style={{ backgroundColor: theme.primary }}>
                    <svg className="w-7 h-7" viewBox="0 0 24 24" style={{ fill: '#ffffff' }}><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z" /></svg>
                  </div>
                </div>
                <h3 className="text-base font-semibold text-slate-900">I have actual measurements</h3>
                <p className="mt-1 text-sm text-slate-500 flex-1">You already have final roof dimensions. Just type them in - no pitch calculation needed.</p>
              </button>
              <button onClick={() => setMeasureMode('plan')}
                className="group w-full rounded-2xl border-2 border-slate-200 bg-white p-6 text-left transition-all cursor-pointer hover:shadow-lg min-h-[180px] flex flex-col"
                onMouseEnter={(e) => { e.currentTarget.style.borderColor = theme.primary; e.currentTarget.style.boxShadow = `0 4px 20px ${theme.primary}15`; }}
                onMouseLeave={(e) => { e.currentTarget.style.borderColor = ''; e.currentTarget.style.boxShadow = ''; }}>
                <div className="flex items-start mb-3">
                  <div className="w-12 h-12 rounded-full flex items-center justify-center" style={{ backgroundColor: theme.primary }}>
                    <svg className="w-7 h-7" viewBox="0 0 24 24" style={{ fill: '#ffffff' }}><path d="M14 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z" /></svg>
                  </div>
                </div>
                <h3 className="text-base font-semibold text-slate-900">I&apos;m measuring from a plan</h3>
                <p className="mt-1 text-sm text-slate-500 flex-1">You have a top-down roof plan. Enter plan dimensions and the roof pitch - we&apos;ll calculate the real sloped lengths and areas.</p>
              </button>
            </div>
          </div>
        )}

        {/* Builder */}
        {measureMode && !showResults && (
          <>
            {/* Breadcrumb / mode strip */}
            <div className="rounded-xl border border-slate-200 bg-slate-50/50 p-3 md:p-4 mb-5 flex items-center justify-between">
              <span className="text-sm font-medium text-slate-700">{measureMode === 'actual' ? 'Actual Measurements Mode' : 'Plan + Pitch Calculation Mode'}</span>
              <button onClick={() => setMeasureMode(null)} className="text-xs font-medium text-slate-400 hover:text-slate-600 transition rounded-full px-3 py-1 hover:bg-slate-100 cursor-pointer">Change mode</button>
            </div>

            {/* Step 1 (plan mode): Roof Pitch */}
            {planStep && (
              <>
                <div className="mb-3">
                  <h2 className="text-base md:text-lg font-bold text-slate-900">Step 1: Roof Pitch</h2>
                  <p className="mt-0.5 text-xs md:text-sm text-slate-400">Add the known roof pitch in degrees or ratio before continuing to Step 2.</p>
                </div>
                <div className="rounded-xl border border-slate-200 bg-slate-50/50 p-3 md:p-5 mb-6">
                  <div className="flex flex-col md:flex-row md:items-center gap-3">
                    <div className="flex items-center gap-2">
                      <svg className="w-5 h-5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M3 12l9-9 9 9M5 10v10h14V10" />
                      </svg>
                      <span className="text-sm font-semibold text-slate-700">Roof Pitch</span>
                      <InfoIcon text="Roof pitch is the angle of the roof slope. E.g. 25 degrees is a common UK roof pitch. We use this to calculate the real sloped lengths from your plan measurements." color={theme.primary} />
                    </div>
                    <div className="flex items-center gap-1 rounded-full border border-slate-200 bg-white p-0.5">
                      <button onClick={() => setPitchMode('degrees')} className={`rounded-full px-3 py-1 text-xs font-medium transition cursor-pointer ${pitchMode === 'degrees' ? 'text-white' : 'text-slate-500'}`} style={pitchMode === 'degrees' ? { backgroundColor: theme.primary } : {}}>Degrees</button>
                      <button onClick={() => setPitchMode('ratio')} className={`rounded-full px-3 py-1 text-xs font-medium transition cursor-pointer ${pitchMode === 'ratio' ? 'text-white' : 'text-slate-500'}`} style={pitchMode === 'ratio' ? { backgroundColor: theme.primary } : {}}>Ratio</button>
                    </div>
                    {pitchMode === 'degrees' ? (
                      <div className="flex items-center gap-2">
                        <div className="relative">
                          <label htmlFor="roof-pitch-degrees" className="sr-only">Roof pitch in degrees</label>
                          <input id="roof-pitch-degrees" name="pitchDegrees" type="number" value={masterPitch} onChange={(e) => updatePitchDegrees(e.target.value)} min={0} max={89} step={0.5} inputMode="decimal" className="w-20 rounded-lg border border-slate-300 px-2 py-1.5 text-base md:text-sm text-center focus:outline-none" style={{ borderColor: theme.primary }} />
                          <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-slate-400">deg</span>
                        </div>
                        <span className="text-xs text-slate-400">= {masterRatio}</span>
                      </div>
                    ) : (
                      <div className="flex items-center gap-2">
                        <label htmlFor="roof-pitch-ratio" className="sr-only">Roof pitch ratio</label>
                        <input id="roof-pitch-ratio" name="pitchRatio" type="text" value={masterRatio} onChange={(e) => updatePitchRatio(e.target.value)} placeholder="5:12" className="w-20 rounded-lg border border-slate-300 px-2 py-1.5 text-base md:text-sm text-center focus:outline-none" style={{ borderColor: theme.primary }} />
                        <span className="text-xs text-slate-400">= {masterPitch} deg</span>
                      </div>
                    )}
                  </div>
                  <div className="mt-3 rounded-xl bg-slate-50 border border-slate-100 p-3">
                    <p className="text-xs text-slate-500">
                      Common pitches: 15 deg (low pitch), 25 deg (standard UK), 35 deg (steep), 45 deg (very steep).
                      {u === 'metric' ? ' Ratio format is rise:10 (e.g. 4.7:10).' : ' Ratio format is rise:12 (e.g. 5:12).'}
                    </p>
                  </div>
                </div>
              </>
            )}

            {/* Step: Roof Area */}
            <div className="mb-3">
              <h2 className="text-base md:text-lg font-bold text-slate-900">{planStep ? 'Step 2' : 'Step 1'}: Roof Area</h2>
              <p className="mt-0.5 text-xs md:text-sm text-slate-400">Enter the width and length, or add the known total area. You can add a different roof covering based on the components available.</p>
            </div>
            {renderSection('roof_area')}

            {/* Step: Components */}
            <div className="mt-6 mb-3">
              <h2 className="text-base md:text-lg font-bold text-slate-900">{planStep ? 'Step 3' : 'Step 2'}: Components</h2>
              <p className="mt-0.5 text-xs md:text-sm text-slate-400">Add quantities for ridges, hips, valleys, barges, spouting, underlay and any other components you need.</p>
            </div>
            <div className="space-y-3">
              {BUILT_IN_ORDER.filter(k => k !== 'roof_area').map(k => renderSection(k))}
              {Object.keys(customSections).map(k => renderSection(k))}
              <CustomComponentCreator theme={theme} onCreate={addCustomComponent} />
            </div>

            {/* Step: Generate */}
            <div className="mt-6 mb-3">
              <h2 className="text-base md:text-lg font-bold text-slate-900">{planStep ? 'Step 4' : 'Step 3'}: Generate</h2>
              <p className="mt-0.5 text-xs md:text-sm text-slate-400">Review your summary and generate your takeoff report.</p>
            </div>
            {hasData ? (
              <div className="rounded-xl bg-slate-900 text-white p-4 md:p-5">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-semibold">Summary</h3>
                  <span className="text-xs text-slate-400">{calculation.totalEntries} {calculation.totalEntries === 1 ? 'entry' : 'entries'} total</span>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                  {allKeys.map(key => {
                    const t = totals[key];
                    if (!t || t.count === 0) return null;
                    const section = allSections[key];
                    const isArea = key === 'roof_area' || key === 'underlay' || key === 'fixings' || (key.startsWith('custom-') && section.customDef?.measurementType === 'area');
                    const du = isArea ? areaLbl : lenLbl;
                    return (
                      <div key={key} className="rounded-lg bg-white/5 border border-white/10 px-3 py-2">
                        <div className="flex items-center gap-1.5">
                          <ComponentSymbol kind={key} customDef={section.customDef} className="w-3 h-3 text-slate-400" />
                          <span className="text-xs text-slate-300 truncate">{componentLabel(key, section.customDef)}</span>
                        </div>
                        <div className="mt-1 text-sm font-semibold">{t.rawTotal.toFixed(2)} {du}</div>
                        {section.wastePercent > 0 && <div className="text-xs text-slate-400">w/ waste: {t.withWaste.toFixed(2)} {du}</div>}
                        {t.totalCost > 0 && <div className="text-xs font-medium mt-0.5" style={{ color: theme.primary }}>{cur}{t.totalCost.toFixed(2)}</div>}
                      </div>
                    );
                  })}
                </div>
                {grandTotal > 0 && (
                  <div className="mt-4 pt-4 border-t border-white/10 flex items-center justify-between">
                    <span className="text-sm font-semibold">Estimated Total</span>
                    <span className="text-xl font-bold">{cur}{grandTotal.toFixed(2)}</span>
                  </div>
                )}
                <button onClick={() => setShowResults(true)}
                  className="mt-4 w-full inline-flex items-center justify-center gap-1.5 rounded-full px-5 py-3 text-sm font-semibold text-white transition-all min-h-[44px]"
                  style={{ backgroundColor: theme.primary }}>
                  Generate Takeoff Report
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" /></svg>
                </button>
              </div>
            ) : (
              <div className="mt-6 rounded-xl border-dashed border border-slate-200 px-6 py-12 text-center">
                <svg className="mx-auto w-10 h-10 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}><path strokeLinecap="round" strokeLinejoin="round" d="M3 12l9-9 9 9M5 10v10h14V10" /></svg>
                <p className="mt-3 text-sm text-slate-500">Start by adding your roof area measurements above.</p>
                <p className="mt-1 text-xs text-slate-400">Then add ridge, hip, valley, barge, spouting, or custom components below.</p>
              </div>
            )}
          </>
        )}

        {showResults && (
          <ResultsModal
            sections={allSections}
            totals={totals}
            getComponentById={getComponentById}
            grandTotal={grandTotal}
            unitSystem={u}
            allKeys={allKeys}
            currencySymbol={cur}
            theme={theme}
            supplierSlug={theme.supplierSlug}
            onClose={() => setShowResults(false)}
            onEdit={() => setShowResults(false)}
          />
        )}
      </div>

      <footer className="border-t border-slate-100 py-4">
        <div className="mx-auto max-w-5xl px-4 flex items-center justify-between">
          <span className="text-xs text-slate-400">{theme.copy.footerText}</span>
          {measureMode && !showResults && (
            <button onClick={startOver} className="text-xs text-slate-400 hover:text-slate-600 transition cursor-pointer">Start over</button>
          )}
        </div>
      </footer>
      <style jsx global>{`
        .roof-takeoff-theme h1,
        .roof-takeoff-theme h2,
        .roof-takeoff-theme h3 { font-family: var(--roof-heading-font); }
      `}</style>
    </main>
  );
}
