'use client';

import { useState, useEffect, type CSSProperties } from 'react';
import Link from 'next/link';
import type {
  ThemeConfig,
  RoofComponentDef,
  MeasureMode,
  PricingMode,
  LayoutChoice,
  RoofType,
  TakeoffCapabilities,
  SupplierAdapter,
  SupplierContext,
  SupplierSummary,
  SupplierCatalogue,
  EnquiryAdapter,
  ResultAdapter,
  TakeoffPrefill,
} from '@roof-takeoff/core';
import { filterComponentsForRoofType, resolvePricingModes, DEFAULT_CAPABILITIES } from '@roof-takeoff/core';
import { FormsLayout } from '@roof-takeoff/layout-forms';
import { ClassicLayout } from '@roof-takeoff/layout-classic';
import { ChoiceIcon, type ChoiceIconName } from '@roof-takeoff/ui';

interface TakeoffFlowProps {
  theme: ThemeConfig;
  components: RoofComponentDef[];
  capabilities?: TakeoffCapabilities;
  supplierAdapter?: SupplierAdapter;
  enquiryAdapter?: EnquiryAdapter;
  resultAdapter?: ResultAdapter;
  initialSupplierSlug?: string;
  prefill?: TakeoffPrefill | null;
  hideHeader?: boolean;
}

type FlowStep = 'supplier' | 'measure' | 'pricing' | 'layout' | 'builder';

export function TakeoffFlow({
  theme,
  components: staticComponents,
  capabilities = DEFAULT_CAPABILITIES,
  supplierAdapter,
  enquiryAdapter,
  resultAdapter,
  initialSupplierSlug,
  prefill = null,
  hideHeader = false,
}: TakeoffFlowProps) {
  const hasSupplierStep = capabilities.supplierSelection === true && !!supplierAdapter;
  const pricing = resolvePricingModes(theme.pricingModes);
  const roofTypeOptions = theme.roofTypeOptions ?? [];
  const defaultRoofType = roofTypeOptions.length === 1 ? roofTypeOptions[0] : null;

  // Prefill answers everything it can so the user lands directly in the builder
  const prefillMode = prefill?.measureMode ?? null;
  const prefillPricing: PricingMode | null = prefill?.pricingMode ?? pricing.defaultMode ?? null;
  const prefillRoofType: RoofType | null = prefill?.roofType ?? defaultRoofType;

  const [step, setStep] = useState<FlowStep>(hasSupplierStep && !initialSupplierSlug ? 'supplier' : prefillMode ? 'builder' : 'measure');
  const [measureMode, setMeasureMode] = useState<MeasureMode | null>(prefillMode);
  const [pricingMode, setPricingMode] = useState<PricingMode | null>(prefillPricing);
  const [roofType, setRoofType] = useState<RoofType | null>(prefillRoofType);
  const [layout, setLayout] = useState<LayoutChoice | null>(prefill?.layout ?? 'fast');

  // Supplier state
  const [supplierCtx, setSupplierCtx] = useState<SupplierContext | null>(null);
  const [supplierList, setSupplierList] = useState<SupplierSummary[]>([]);
  const [supplierSearchQuery, setSupplierSearchQuery] = useState('');
  const [supplierLoading, setSupplierLoading] = useState(false);
  const [supplierError, setSupplierError] = useState<string | null>(null);
  const [catalogueLoading, setCatalogueLoading] = useState(false);
  const [catalogueError, setCatalogueError] = useState<string | null>(null);
  const [activeComponents, setActiveComponents] = useState<RoofComponentDef[]>(staticComponents);
  const [activeTheme, setActiveTheme] = useState(theme);

  // Scroll to top whenever step changes
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [step]);

  // Preselected supplier: load catalogue on mount
  if (initialSupplierSlug && !supplierCtx && !catalogueLoading && hasSupplierStep) {
    setCatalogueLoading(true);
    setSupplierError(null);
    supplierAdapter!.loadCatalogue(initialSupplierSlug).then((cat: SupplierCatalogue) => {
      setSupplierCtx({
        slug: cat.slug,
        name: cat.supplierName,
        currency: cat.currency,
        currencySymbol: cat.currencySymbol,
        unitSystem: cat.unitSystem,
        catalogueVersion: cat.catalogueVersion ?? null,
      });
      setActiveComponents(cat.components);
      setActiveTheme({
        ...theme,
        currency: cat.currency,
        currencySymbol: cat.currencySymbol,
        defaultUnits: cat.unitSystem,
        pricingModes: cat.pricingModes ?? theme.pricingModes,
        roofTypeOptions: cat.roofTypeOptions ?? theme.roofTypeOptions,
        supplierName: cat.supplierName,
        supplierEmail: cat.supplierEmail ?? null,
        supplierSlug: cat.slug,
      });
      setCatalogueLoading(false);
    }).catch((err) => {
      setCatalogueError(err instanceof Error ? err.message : 'Failed to load supplier catalogue');
      setCatalogueLoading(false);
    });
  }

  // Auto-load supplier list when supplier step is shown (no initial slug)
  useEffect(() => {
    if (step === 'supplier' && supplierAdapter && supplierList.length === 0 && !supplierLoading && !supplierError) {
      setSupplierLoading(true);
      supplierAdapter.listSuppliers({}).then((results) => {
        setSupplierList(results);
        setSupplierLoading(false);
      }).catch((err) => {
        setSupplierError(err instanceof Error ? err.message : 'Failed to load suppliers');
        setSupplierLoading(false);
      });
    }
  }, [step, supplierAdapter, supplierList.length, supplierLoading, supplierError]);

  const hasPricingStep = pricing.hasChoice || roofTypeOptions.length > 1;
  const availableComponents = filterComponentsForRoofType(activeComponents, roofType);

  const handleMeasureChoice = (mode: MeasureMode) => {
    setMeasureMode(mode);
    if (hasPricingStep) {
      setStep('pricing');
    } else {
      setStep('layout');
    }
  };

  const handlePricingChoice = (mode: PricingMode) => {
    setPricingMode(mode);
  };

  const handlePricingContinue = () => {
    setStep('layout');
  };

  const handleLayoutChoice = (choice: LayoutChoice) => {
    setLayout(choice);
    setStep('builder');
  };

  const handleSwitchLayout = (choice: LayoutChoice) => {
    setLayout(choice);
  };

  // Supplier handlers
  const handleSupplierSearch = async () => {
    if (!supplierAdapter) return;
    setSupplierLoading(true);
    setSupplierError(null);
    try {
      const results = await supplierAdapter.listSuppliers({ query: supplierSearchQuery });
      setSupplierList(results);
    } catch (err) {
      setSupplierError(err instanceof Error ? err.message : 'Failed to search suppliers');
    } finally {
      setSupplierLoading(false);
    }
  };

  const handleSupplierSelect = async (slug: string) => {
    if (!supplierAdapter) return;
    setCatalogueLoading(true);
    setCatalogueError(null);
    try {
      const cat = await supplierAdapter.loadCatalogue(slug);
      setSupplierCtx({
        slug: cat.slug,
        name: cat.supplierName,
        currency: cat.currency,
        currencySymbol: cat.currencySymbol,
        unitSystem: cat.unitSystem,
        catalogueVersion: cat.catalogueVersion ?? null,
      });
      setActiveComponents(cat.components);
      setActiveTheme({
        ...theme,
        currency: cat.currency,
        currencySymbol: cat.currencySymbol,
        defaultUnits: cat.unitSystem,
        pricingModes: cat.pricingModes ?? theme.pricingModes,
        roofTypeOptions: cat.roofTypeOptions ?? theme.roofTypeOptions,
        supplierName: cat.supplierName,
        supplierEmail: cat.supplierEmail ?? null,
        supplierSlug: cat.slug,
      });
      setStep(prefillMode ? 'builder' : 'measure');
    } catch (err) {
      setCatalogueError(err instanceof Error ? err.message : 'Failed to load supplier catalogue');
    } finally {
      setCatalogueLoading(false);
    }
  };

  const handleSupplierSkip = () => {
    setStep(prefillMode ? 'builder' : 'measure');
  };

  // Render the chosen layout
  if (step === 'builder' && layout && measureMode) {
    // Prefilled units apply until a supplier catalogue overrides them
    const flowTheme = prefill?.unitSystem && !supplierCtx ? { ...activeTheme, defaultUnits: prefill.unitSystem } : activeTheme;
    if (layout === 'guided') {
      return (
        <FormsLayout
          theme={flowTheme}
          components={availableComponents}
          initialMeasureMode={measureMode}
          pricingMode={pricingMode}
          onSwitchLayout={handleSwitchLayout}
          capabilities={capabilities}
          prefill={prefill}
        />
      );
    }
    return (
      <ClassicLayout
        theme={flowTheme}
        components={availableComponents}
      initialMeasureMode={measureMode}
      pricingMode={pricingMode}
      onSwitchLayout={handleSwitchLayout}
      capabilities={capabilities}
      prefill={prefill}
    />
    );
  }

  // Step screens
  return (
    <main
      className="roof-takeoff-theme min-h-screen bg-white flex flex-col"
      style={{ fontFamily: activeTheme.bodyFont, '--roof-heading-font': activeTheme.headingFont } as CSSProperties}
    >
      {!hideHeader && (
      <header className="border-b border-slate-100 sticky top-0 z-10 bg-white/95 backdrop-blur-sm">
        <div className="mx-auto max-w-2xl px-4 py-3 flex items-center justify-between">
          <Link href="/" className="flex items-center">
            {activeTheme.logoUrl ? (
              <img src={activeTheme.logoUrl} alt={activeTheme.supplierName ?? activeTheme.copy.headerTitle} className="h-8 md:h-10 w-auto" />
            ) : (
              <span className="text-sm font-semibold text-slate-900">{activeTheme.copy.headerTitle}</span>
            )}
          </Link>
          {activeTheme.copy.poweredBy && (
            <span className="text-xs text-slate-400">{activeTheme.copy.poweredBy}</span>
          )}
        </div>
        {/* Progress bar */}
        {step !== 'supplier' && step !== 'measure' && (
          <div className="h-1 bg-slate-100">
            <div
              className="h-full transition-all duration-300 ease-out"
              style={{
                width: `${step === 'pricing' ? 33 : step === 'layout' ? (hasPricingStep ? 66 : 50) : 100}%`,
                backgroundColor: activeTheme.primary,
              }}
            />
          </div>
        )}
      </header>
      )}

      <div className="flex-1 mx-auto w-full max-w-2xl px-4 py-8 md:py-12">
        {step === 'supplier' && hasSupplierStep && (
          <>
          {/* Intro explainer - shown only on supplier step (initial landing) */}
          <div className="mb-8 md:mb-10 grid grid-cols-1 md:grid-cols-4 gap-3 md:gap-4">
            <div className="rounded-xl border border-slate-200 bg-white p-4 flex flex-col items-center text-center">
              <div className="w-9 h-9 rounded-full bg-orange-50 flex items-center justify-center mb-2">
                <svg className="w-4.5 h-4.5 text-[#FF6B35]" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <h3 className="text-sm font-semibold text-slate-900">No signup required</h3>
              <p className="mt-1 text-xs text-slate-500">Use the full tool without creating an account.</p>
            </div>
            <div className="rounded-xl border border-slate-200 bg-white p-4 flex flex-col items-center text-center">
              <div className="w-9 h-9 rounded-full bg-orange-50 flex items-center justify-center mb-2">
                <svg className="w-4.5 h-4.5 text-[#FF6B35]" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                  <path strokeLinecap="round" strokeLinejoin="round" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                </svg>
              </div>
              <h3 className="text-sm font-semibold text-slate-900">Find a supplier</h3>
              <p className="mt-1 text-xs text-slate-500">Browse suppliers near you with real component pricing.</p>
            </div>
            <div className="rounded-xl border border-slate-200 bg-white p-4 flex flex-col items-center text-center">
              <div className="w-9 h-9 rounded-full bg-orange-50 flex items-center justify-center mb-2">
                <svg className="w-4.5 h-4.5 text-[#FF6B35]" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
                </svg>
              </div>
              <h3 className="text-sm font-semibold text-slate-900">Get pricing</h3>
              <p className="mt-1 text-xs text-slate-500">Enter measurements and get a preliminary material takeoff.</p>
            </div>
            <div className="rounded-xl border border-slate-200 bg-white p-4 flex flex-col items-center text-center">
              <div className="w-9 h-9 rounded-full bg-orange-50 flex items-center justify-center mb-2">
                <svg className="w-4.5 h-4.5 text-[#FF6B35]" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                </svg>
              </div>
              <h3 className="text-sm font-semibold text-slate-900">Download or send</h3>
              <p className="mt-1 text-xs text-slate-500">Export your takeoff or send it to a supplier for a quote.</p>
            </div>
          </div>
          <SupplierStep
            theme={activeTheme}
            searchQuery={supplierSearchQuery}
            onSearchQueryChange={setSupplierSearchQuery}
            onSearch={handleSupplierSearch}
            onSkip={handleSupplierSkip}
            suppliers={supplierList}
            onSelect={handleSupplierSelect}
            loading={supplierLoading}
            catalogueLoading={catalogueLoading}
            error={supplierError || catalogueError}
            preselectedSlug={initialSupplierSlug}
          />
          </>
        )}

        {step === 'supplier' && catalogueLoading && initialSupplierSlug && (
          <div className="text-center py-12">
            <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-slate-200 border-t-slate-900" />
            <p className="mt-4 text-sm text-slate-500">Loading supplier catalogue...</p>
          </div>
        )}

        {step === 'measure' && (
          <ChoiceScreen
            title="How do you want to enter your measurements?"
            subtitle="Choose the method that matches your measurements."
            theme={activeTheme}
            options={[
              {
                title: 'I have actual measurements',
                description: 'You already have final roof dimensions. Just type them in - no pitch calculation needed.',
                icon: 'actual',
                onClick: () => handleMeasureChoice('actual'),
              },
              {
                title: "I'm measuring from a plan",
                description: 'You have a top-down roof plan. Enter plan dimensions and the roof pitch - we will calculate the real sloped lengths and areas.',
                icon: 'plan',
                onClick: () => handleMeasureChoice('plan'),
              },
            ]}
          />
        )}

        {step === 'pricing' && hasPricingStep && (
          <PricingScreen
            theme={activeTheme}
            pricingModes={pricing.modes}
            pricingMode={pricingMode}
            roofTypeOptions={roofTypeOptions}
            roofType={roofType}
            onSelectPricing={handlePricingChoice}
            onSelectRoofType={setRoofType}
            onContinue={handlePricingContinue}
            onBack={() => { setStep('measure'); setMeasureMode(null); }}
          />
        )}

        {step === 'layout' && (
          <ChoiceScreen
            title="How would you like to build your takeoff?"
            subtitle="Choose the experience that suits you. You can switch at any time."
            theme={activeTheme}
            stepLabel={hasPricingStep ? 'Step 3' : 'Step 2'}
            onBack={() => {
              if (hasPricingStep) {
                setStep('pricing');
              } else {
                setStep('measure');
                setMeasureMode(null);
              }
            }}
            options={[
              {
                title: 'Guided',
                description: 'Step-by-step wizard with one section per page. Great for first-time users or when you want extra guidance.',
                icon: 'guided',
                badge: 'Recommended',
                onClick: () => handleLayoutChoice('guided'),
              },
              {
                title: 'Fast',
                description: 'All sections on one page with expandable accordions. Best for experienced users who want to move quickly.',
                icon: 'fast',
                onClick: () => handleLayoutChoice('fast'),
              },
            ]}
          />
        )}
      </div>

      <footer className="border-t border-slate-100 py-4">
        <div className="mx-auto max-w-2xl px-4 flex items-center justify-between">
          <span className="text-xs text-slate-400">{activeTheme.copy.footerText}</span>
          {supplierCtx && (
            <span className="text-xs text-slate-400">Using {supplierCtx.name}</span>
          )}
        </div>
      </footer>
      <style jsx global>{`
        .roof-takeoff-theme h1,
        .roof-takeoff-theme h2,
        .roof-takeoff-theme h3 { font-family: var(--roof-heading-font); }
      `}</style>
    </main>
  );
}

// ─── Supplier Step ───────────────────────────────────

function SupplierStep({
  theme,
  searchQuery,
  onSearchQueryChange,
  onSearch,
  onSkip,
  suppliers,
  onSelect,
  loading,
  catalogueLoading,
  error,
  preselectedSlug,
}: {
  theme: ThemeConfig;
  searchQuery: string;
  onSearchQueryChange: (v: string) => void;
  onSearch: () => void;
  onSkip: () => void;
  suppliers: SupplierSummary[];
  onSelect: (slug: string) => void;
  loading: boolean;
  catalogueLoading: boolean;
  error: string | null;
  preselectedSlug?: string;
}) {
  return (
    <div className="animate-[fadeIn_0.3s_ease-out]">
      <h1 className="text-xl md:text-2xl font-semibold text-slate-900">Step 1: Choose a supplier</h1>
      <p className="mt-2 text-sm text-slate-500">
        Pick a supplier to use their real component pricing, or use QuoteCore+ default to continue with test pricing.
      </p>

      {/* QuoteCore+ default - always at top, acts as skip */}
      <button
        onClick={onSkip}
        className="mt-5 w-full text-left rounded-xl border-2 border-[#FF6B35] bg-orange-50/40 p-4 transition-all cursor-pointer hover:border-[#FF6B35] hover:shadow-[0_0_16px_rgba(255,107,53,0.2)] hover:bg-orange-50/60 group"
      >
        <div className="flex items-center justify-between">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              <h3 className="text-base font-bold text-slate-900 group-hover:text-[#BD4A1A] transition">QuoteCore+</h3>
              <span className="rounded-full bg-[#FF6B35] px-2.5 py-1 text-xs font-medium text-white">Default</span>
            </div>
            <p className="mt-1 text-sm text-slate-600">Use the tool with default test pricing - no supplier needed. Pick a real supplier below for accurate pricing.</p>
            <div className="mt-1.5 flex items-center gap-2 flex-wrap">
              <span className="rounded-full bg-slate-100 px-2 py-0.5 text-xs text-slate-500">All countries</span>
              <span className="rounded-full bg-slate-100 px-2 py-0.5 text-xs text-slate-500">USD</span>
            </div>
          </div>
          <svg className="w-5 h-5 text-[#FF6B35] group-hover:text-[#BD4A1A] transition flex-shrink-0 ml-2" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" /></svg>
        </div>
      </button>

      <div className="mt-6 flex gap-2">
        <input
          type="text"
          value={searchQuery}
          onChange={(e) => onSearchQueryChange(e.target.value)}
          onKeyDown={(e) => { if (e.key === 'Enter') onSearch(); }}
          placeholder="Search suppliers by name or region..."
          className="flex-1 rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none"
        />
        <button
          onClick={onSearch}
          disabled={loading}
          className="cursor-pointer rounded-lg px-5 py-2.5 text-sm font-semibold text-white transition min-h-[44px] disabled:opacity-50"
          style={{ backgroundColor: theme.primary }}
        >
          {loading ? 'Searching...' : 'Search'}
        </button>
      </div>

      {error && (
        <div className="mt-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3">
          <p className="text-sm text-red-700">{error}</p>
          <button onClick={() => onSelect(preselectedSlug || '')} className="mt-2 text-xs font-medium text-red-700 hover:underline">Retry</button>
        </div>
      )}

      {suppliers.length > 0 && (
        <div className="mt-6 space-y-3">
          {suppliers.map((s) => (
            <button
              key={s.slug}
              onClick={() => onSelect(s.slug)}
              disabled={catalogueLoading}
              className="w-full text-left rounded-2xl border-2 border-slate-200 bg-white p-5 transition-all cursor-pointer hover:shadow-lg hover:border-slate-300 disabled:opacity-50"
            >
              <div className="flex items-center gap-4">
                {s.logoUrl && (
                  <img src={s.logoUrl} alt={s.name} className="h-10 w-10 rounded object-contain flex-shrink-0" />
                )}
                <div className="flex-1 min-w-0">
                  <h3 className="text-base font-semibold text-slate-900">{s.name}</h3>
                  <p className="text-sm text-slate-500">
                    {[s.branchCity, s.branchRegion].filter(Boolean).join(', ')}
                    {s.currency ? ` · ${s.currency}` : ''}
                  </p>
                </div>
                <svg className="w-5 h-5 text-slate-300 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" />
                </svg>
              </div>
            </button>
          ))}
        </div>
      )}

      {!loading && suppliers.length === 0 && !error && (
        <div className="mt-6 rounded-xl border-dashed border-slate-200 border-2 px-6 py-12 text-center">
          <p className="text-sm text-slate-500">No suppliers found. Try searching, or skip to use default pricing.</p>
        </div>
      )}

      {catalogueLoading && (
        <div className="mt-6 text-center">
          <div className="inline-block h-6 w-6 animate-spin rounded-full border-4 border-slate-200 border-t-slate-900" />
          <p className="mt-2 text-sm text-slate-500">Loading catalogue...</p>
        </div>
      )}

      <p className="mt-6 text-center text-xs text-slate-400">
        You can adjust any price after selecting a supplier. No commitment.
      </p>
    </div>
  );
}

// ─── Pricing Screen (with roof type selector) ────────

function PricingScreen({
  theme,
  pricingModes,
  pricingMode,
  roofTypeOptions,
  roofType,
  onSelectPricing,
  onSelectRoofType,
  onContinue,
  onBack,
}: {
  theme: ThemeConfig;
  pricingModes: PricingMode[];
  pricingMode: PricingMode | null;
  roofTypeOptions: RoofType[];
  roofType: RoofType | null;
  onSelectPricing: (mode: PricingMode) => void;
  onSelectRoofType: (type: RoofType) => void;
  onContinue: () => void;
  onBack: () => void;
}) {
  const canContinue = pricingMode !== null && (roofTypeOptions.length < 2 || roofType !== null);

  return (
    <div className="animate-[fadeIn_0.3s_ease-out]">
      <span className="text-xs font-medium text-slate-400 mb-2 block">Step 2</span>
      <h1 className="text-xl md:text-2xl font-semibold text-slate-900">
        {pricingModes.length > 1 ? 'What pricing do you need?' : 'What type of roofing job is this?'}
      </h1>
      <p className="mt-2 text-sm text-slate-500">
        {pricingModes.length > 1
          ? 'Choose your pricing and job type so we use the correct catalogue.'
          : 'Choose the job type so we use the correct component and pricing catalogue.'}
      </p>

      {/* Pricing mode choice cards */}
      {pricingModes.length > 1 && (
        <div className="mt-6 md:mt-8 space-y-3">
          {pricingModes.includes('material') && (
            <PricingCard
              theme={theme}
              title="Material only"
              description="See material costs only. No labour or installation costs shown."
              icon="material"
              selected={pricingMode === 'material'}
              onClick={() => onSelectPricing('material')}
            />
          )}
          {pricingModes.includes('material_install') && (
            <PricingCard
              theme={theme}
              title="Material and install"
              description="See full pricing including materials, labour and installation costs."
              icon="install"
              selected={pricingMode === 'material_install'}
              onClick={() => onSelectPricing('material_install')}
            />
          )}
        </div>
      )}

      {roofTypeOptions.length > 1 && (
        <div className="mt-6 rounded-2xl border-2 border-slate-200 bg-slate-50/50 p-5 md:p-6">
          <h3 className="text-sm font-semibold text-slate-900">What type of job is this?</h3>
          <p className="mt-1 text-xs text-slate-500">Your selection controls which products and prices are available.</p>
          <div className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2">
            {roofTypeOptions.map(option => (
              <RoofTypeOption
                key={option}
                theme={theme}
                label={option === 'new_roof' ? 'New roof' : 'Re-roof'}
                description={option === 'new_roof' ? 'Brand new roof installation' : 'Replacing an existing roof'}
                selected={roofType === option}
                onClick={() => onSelectRoofType(option)}
              />
            ))}
          </div>
        </div>
      )}

      {/* Continue / Back */}
      <div className="mt-8 flex items-center justify-between gap-3">
        <button
          onClick={onBack}
          className="cursor-pointer rounded-lg px-4 py-2.5 text-sm font-medium text-slate-500 hover:text-slate-700 hover:bg-slate-50 transition min-h-[44px]"
        >
          <svg className="w-4 h-4 inline mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" />
          </svg>
          Back
        </button>
        <button
          onClick={onContinue}
          disabled={!canContinue}
          className="cursor-pointer rounded-lg px-6 py-2.5 text-sm font-semibold text-white transition min-h-[44px]"
          style={canContinue ? { backgroundColor: theme.primary } : { backgroundColor: '#e2e8f0', color: '#94a3b8', cursor: 'not-allowed' }}
        >
          Continue
          <svg className="w-4 h-4 inline ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" />
          </svg>
        </button>
      </div>
    </div>
  );
}

// ─── Pricing Card (selectable) ───────────────────────

function PricingCard({
  theme,
  title,
  description,
  icon,
  selected,
  onClick,
}: {
  theme: ThemeConfig;
  title: string;
  description: string;
  icon: ChoiceIconName;
  selected: boolean;
  onClick: () => void;
}) {
  return (
    <button
      onClick={onClick}
      className="w-full text-left rounded-2xl border-2 bg-white p-5 md:p-6 transition-all cursor-pointer hover:shadow-lg group"
      style={{
        borderColor: selected ? theme.primary : undefined,
        boxShadow: selected ? `0 4px 20px ${theme.primary}15` : undefined,
      }}
      onMouseEnter={(e) => {
        if (!selected) {
          e.currentTarget.style.borderColor = theme.primary;
          e.currentTarget.style.boxShadow = `0 4px 20px ${theme.primary}15`;
        }
      }}
      onMouseLeave={(e) => {
        if (!selected) {
          e.currentTarget.style.borderColor = '';
          e.currentTarget.style.boxShadow = '';
        }
      }}
    >
      <div className="flex items-start gap-4">
        <div
          className="w-12 h-12 rounded-full flex items-center justify-center flex-shrink-0 text-white"
          style={{ backgroundColor: theme.primary }}
        >
          <ChoiceIcon icon={icon} />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <h3 className="text-base md:text-lg font-semibold text-slate-900">{title}</h3>
            {selected && (
              <span
                className="rounded-full p-1 flex items-center justify-center"
                style={{ backgroundColor: theme.primary }}
              >
                <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                </svg>
              </span>
            )}
          </div>
          <p className="mt-1 text-sm text-slate-500">{description}</p>
        </div>
      </div>
    </button>
  );
}


// ─── Choice Screen ───────────────────────────────────

function RoofTypeOption({
  theme,
  label,
  description,
  selected,
  onClick,
}: {
  theme: ThemeConfig;
  label: string;
  description: string;
  selected: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="cursor-pointer rounded-xl border-2 bg-white p-4 text-left transition-all hover:shadow-md"
      style={{ borderColor: selected ? theme.primary : undefined }}
    >
      <div className="flex items-center gap-2.5">
        <span
          className="flex h-5 w-5 flex-shrink-0 items-center justify-center rounded-full border-2 transition"
          style={{
            borderColor: selected ? theme.primary : '#cbd5e1',
            backgroundColor: selected ? theme.primary : 'transparent',
          }}
        >
          {selected && <span className="h-2 w-2 rounded-full bg-white" />}
        </span>
        <span className="min-w-0">
          <span className="block text-sm font-semibold text-slate-900">{label}</span>
          <span className="mt-0.5 block text-xs text-slate-500">{description}</span>
        </span>
      </div>
    </button>
  );
}

interface ChoiceOption {
  title: string;
  description: string;
  icon: ChoiceIconName;
  badge?: string;
  onClick: () => void;
}

function ChoiceScreen({
  title,
  subtitle,
  theme,
  options,
  stepLabel,
  onBack,
}: {
  title: string;
  subtitle?: string;
  theme: ThemeConfig;
  options: ChoiceOption[];
  stepLabel?: string;
  onBack?: () => void;
}) {
  return (
    <div className="animate-[fadeIn_0.3s_ease-out]">
      {stepLabel && <span className="text-xs font-medium text-slate-400 mb-2 block">{stepLabel}</span>}
      <h1 className="text-xl md:text-2xl font-semibold text-slate-900">{title}</h1>
      {subtitle && <p className="mt-2 text-sm text-slate-500">{subtitle}</p>}

      <div className="mt-6 md:mt-8 space-y-3">
        {options.map((opt, idx) => (
          <ChoiceCard key={idx} theme={theme} {...opt} />
        ))}
      </div>

      {onBack && (
        <button
          onClick={onBack}
          className="mt-6 cursor-pointer rounded-lg px-4 py-2.5 text-sm font-medium text-slate-500 hover:text-slate-700 hover:bg-slate-50 transition min-h-[44px]"
        >
          <svg className="w-4 h-4 inline mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" />
          </svg>
          Back
        </button>
      )}
    </div>
  );
}

// ─── Choice Card ─────────────────────────────────────

function ChoiceCard({
  theme,
  title,
  description,
  icon,
  badge,
  onClick,
}: {
  theme: ThemeConfig;
  title: string;
  description: string;
  icon: ChoiceIconName;
  badge?: string;
  onClick: () => void;
}) {
  return (
    <button
      onClick={onClick}
      className="w-full text-left rounded-2xl border-2 border-slate-200 bg-white p-5 md:p-6 transition-all cursor-pointer hover:shadow-lg group"
      onMouseEnter={(e) => {
        e.currentTarget.style.borderColor = theme.primary;
        e.currentTarget.style.boxShadow = `0 4px 20px ${theme.primary}15`;
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.borderColor = '';
        e.currentTarget.style.boxShadow = '';
      }}
    >
      <div className="flex items-start gap-4">
        <div
          className="w-12 h-12 rounded-full flex items-center justify-center flex-shrink-0 text-white"
          style={{ backgroundColor: theme.primary }}
        >
          <ChoiceIcon icon={icon} />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <h3 className="text-base md:text-lg font-semibold text-slate-900">{title}</h3>
            {badge && (
              <span
                className="rounded-full px-2.5 py-0.5 text-xs font-medium text-white"
                style={{ backgroundColor: theme.primary }}
              >
                {badge}
              </span>
            )}
          </div>
          <p className="mt-1 text-sm text-slate-500">{description}</p>
        </div>
        <svg
          className="w-5 h-5 text-slate-300 group-hover:text-slate-400 transition flex-shrink-0 mt-1"
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth={2}
        >
          <path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" />
        </svg>
      </div>
    </button>
  );
}
