'use client';

import { useEffect, useState } from 'react';
import type { ThemeConfig, ComponentSection, RoofComponentDef } from '@roof-takeoff/core';
import { COMPONENT_DEFS, computeMaterialCost, computeKnownPriceCost, computeLabourCost } from '@roof-takeoff/core';
import { componentLabel } from '@roof-takeoff/core';
import { SupplierEnquiryModal } from './SupplierEnquiryModal';

interface ResultsModalProps {
  sections: Record<string, ComponentSection>;
  totals: Record<string, { rawTotal: number; withWaste: number; count: number; materialCost: number; labourCost: number; totalCost: number }>;
  getComponentById: (id: string | null) => RoofComponentDef | null;
  grandTotal: number;
  unitSystem: 'metric' | 'imperial' | 'squares';
  allKeys: string[];
  currencySymbol: string;
  theme: ThemeConfig;
  supplierSlug?: string | null;
  onClose: () => void;
  onEdit: () => void;
}

export function ResultsModal({ sections, totals, getComponentById, grandTotal, unitSystem, allKeys, currencySymbol, theme, supplierSlug, onClose, onEdit }: ResultsModalProps) {
  const cur = currencySymbol;
  const hasPricing = grandTotal > 0;
  const lenUnit = unitSystem === 'metric' ? 'm' : 'ft';
  const areaUnit = unitSystem === 'metric' ? 'm\u00B2' : unitSystem === 'imperial' ? 'sq ft' : 'squares';

  useEffect(() => {
    function handleBeforePrint() {
      const el = document.getElementById('takeoff-print');
      if (el) { document.body.appendChild(el); el.style.position = 'static'; el.style.width = '100%'; el.style.maxWidth = 'none'; el.style.maxHeight = 'none'; el.style.height = 'auto'; el.style.overflow = 'visible'; el.style.borderRadius = '0'; el.style.boxShadow = 'none'; el.style.margin = '0'; el.style.padding = '0'; }
      document.body.querySelectorAll(':scope > *:not(#takeoff-print)').forEach(node => { (node as HTMLElement).style.display = 'none'; });
    }
    function handleAfterPrint() {
      const el = document.getElementById('takeoff-print');
      if (el) { const root = document.getElementById('print-root'); if (root) root.appendChild(el); el.style.position = ''; el.style.width = ''; el.style.maxWidth = ''; el.style.maxHeight = ''; el.style.height = ''; el.style.overflow = ''; el.style.borderRadius = ''; el.style.boxShadow = ''; el.style.margin = ''; el.style.padding = ''; }
      document.body.querySelectorAll(':scope > *').forEach(node => { (node as HTMLElement).style.display = ''; });
    }
    window.addEventListener('beforeprint', handleBeforePrint);
    window.addEventListener('afterprint', handleAfterPrint);
    return () => { window.removeEventListener('beforeprint', handleBeforePrint); window.removeEventListener('afterprint', handleAfterPrint); };
  }, []);

  const [showEnquiry, setShowEnquiry] = useState(false);

  const unitFor = (key: string) => {
    const section = sections[key];
    if (key === 'roof_area' || key === 'underlay' || key === 'fixings') return areaUnit;
    if (key.startsWith('custom-') && section?.customDef?.measurementType === 'fixed') return 'pcs';
    if (key.startsWith('custom-') && section?.customDef?.measurementType === 'area') return areaUnit;
    return lenUnit;
  };

  const handleSendToSupplier = () => {
    setShowEnquiry(true);
  };

  return (
    <div id="print-root" className="fixed inset-0 z-50 flex items-center justify-center backdrop-blur-sm bg-black/40 p-2 md:p-4 print:block print:static print:p-0 print:bg-white">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-3xl max-h-[90vh] overflow-hidden flex flex-col print:shadow-none print:rounded-none print:max-h-none print:w-full print:max-w-none print:overflow-visible" id="takeoff-print">
        <div className="flex items-center justify-between px-4 md:px-6 py-3 md:py-4 border-b border-slate-100 print:border-slate-300">
          <div>
            <h2 className="text-base md:text-lg font-semibold text-slate-900">Roof Takeoff Report</h2>
            <p className="text-xs text-slate-400">Generated {new Date().toLocaleDateString('en-GB')}</p>
          </div>
          <button onClick={onClose} className="cursor-pointer p-2 text-slate-400 hover:text-slate-600 transition rounded-full hover:bg-slate-50 print:hidden min-h-[44px] min-w-[44px] flex items-center justify-center">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="overflow-y-auto px-4 md:px-6 py-4 md:py-5 space-y-5 print:overflow-visible print:px-6 print:py-2">
          {allKeys.map(key => {
            const section = sections[key]; if (!section) return null;
            const t = totals[key]; if (!t || t.count === 0) return null;
            const label = componentLabel(key);
            const pitchType = key === 'roof_area' ? 'rafter' : key.startsWith('custom-') ? (section.customDef?.pitchType ?? 'none') : (COMPONENT_DEFS[key]?.pitchType ?? 'none');
            const isFixed = key.startsWith('custom-') && section.customDef?.measurementType === 'fixed';
            return (
              <div key={key} className="print:break-inside-avoid">
                <div className="flex items-center gap-2 mb-2">
                  <h3 className="text-sm font-semibold text-slate-900">{label}</h3>
                  <span className="text-xs text-slate-400">({t.count} {t.count === 1 ? 'entry' : 'entries'})</span>
                </div>
                <div className="space-y-1 mb-2">
                  {section.entries.map((entry, idx) => {
                    const comp = getComponentById(entry.selectedComponentId);
                    const costQty = isFixed ? (entry.quantity ?? 1) : entry.computedValue;
                    const hasKnownPrice = entry.knownPrice != null && entry.knownPrice > 0;
                    const matCost = hasKnownPrice ? { cost: computeKnownPriceCost(costQty, entry.knownPrice!), packs: 0 } : comp ? computeMaterialCost(costQty, comp) : { cost: 0, packs: 0 };
                    const labCost = hasKnownPrice ? 0 : comp ? computeLabourCost(costQty, comp) : 0;
                    const entryTotal = matCost.cost + labCost;
                    return (
                      <div key={entry.id} className="flex items-center justify-between rounded-lg bg-slate-50 px-3 py-1.5 text-xs print:bg-white print:border print:border-slate-100">
                        <div className="min-w-0 flex-1">
                          <span className="text-slate-500">{entry.label || `Entry ${idx + 1}`}</span>
                          {comp && <span className="ml-2 text-slate-400 truncate">{comp.name}</span>}
                          {hasKnownPrice && <span className="ml-2 text-slate-400 truncate">Known price {cur}{entry.knownPrice!.toFixed(2)}/{isFixed ? 'pc' : unitFor(key)}</span>}
                        </div>
                        <div className="flex items-center gap-3 flex-shrink-0">
                          <span className="font-medium text-slate-700">{entry.computedValue.toFixed(2)} {unitFor(key)}</span>
                          {entryTotal > 0 && <span className="font-medium" style={{ color: theme.primary }}>{cur}{entryTotal.toFixed(2)}</span>}
                        </div>
                      </div>
                    );
                  })}
                </div>
                <div className="flex items-center justify-between rounded-lg border border-slate-200 px-3 py-2">
                  <div className="text-xs text-slate-500">Subtotal{section.wastePercent > 0 && <span className="ml-2">+ {section.wastePercent}% waste</span>}</div>
                  <div className="text-right">
                    <span className="text-sm font-semibold text-slate-900">{t.withWaste.toFixed(2)} {unitFor(key)}</span>
                    {t.totalCost > 0 && <div className="text-xs font-medium" style={{ color: theme.primary }}>Material: {cur}{t.materialCost.toFixed(2)}{t.labourCost > 0 ? ` + Labour: ${cur}${t.labourCost.toFixed(2)}` : ''} = {cur}{t.totalCost.toFixed(2)}</div>}
                  </div>
                </div>
              </div>
            );
          })}

          {hasPricing && (
            <div className="rounded-xl bg-slate-900 text-white p-4 space-y-2 print:break-inside-avoid">
              <div className="flex items-center justify-between"><span className="text-sm font-semibold">Total Materials</span><span className="text-lg font-bold">{cur}{allKeys.reduce((s, k) => s + (totals[k]?.materialCost ?? 0), 0).toFixed(2)}</span></div>
              <div className="flex items-center justify-between"><span className="text-sm font-semibold">Total Labour</span><span className="text-lg font-bold">{cur}{allKeys.reduce((s, k) => s + (totals[k]?.labourCost ?? 0), 0).toFixed(2)}</span></div>
              <div className="flex items-center justify-between pt-2 border-t border-white/10"><span className="text-sm font-semibold">Grand Total</span><span className="text-xl font-bold">{cur}{grandTotal.toFixed(2)}</span></div>
            </div>
          )}
        </div>

        <div className="flex items-center justify-between gap-2 px-4 md:px-6 py-3 md:py-4 border-t border-slate-100 print:hidden">
          <button onClick={() => window.print()} className="cursor-pointer inline-flex items-center gap-1.5 rounded-lg border border-slate-300 px-3 md:px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-50 transition min-h-[44px]">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
            <span className="hidden md:inline">Print / PDF</span>
          </button>
          <div className="flex items-center gap-2">
            <button onClick={onEdit} className="cursor-pointer inline-flex items-center gap-1.5 rounded-lg border border-slate-300 px-3 md:px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-50 transition min-h-[44px]">
              <svg className="w-4 h-4 md:hidden" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
              <span className="hidden md:inline">Edit</span>
            </button>
            {theme.features.sendToSupplier && theme.supplierEmail && (
              <button onClick={handleSendToSupplier} className="cursor-pointer inline-flex items-center gap-1.5 rounded-lg px-3 md:px-4 py-2 text-sm font-semibold text-white transition min-h-[44px]" style={{ backgroundColor: theme.primary }}>
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" /></svg>
                <span className="hidden md:inline">Send to {theme.supplierName}</span>
                <span className="md:hidden">Send</span>
              </button>
            )}
            <button onClick={onClose} className="cursor-pointer inline-flex items-center justify-center rounded-lg border border-slate-300 px-3 md:px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-50 transition min-h-[44px]">
              <svg className="w-4 h-4 md:hidden" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
              <span className="hidden md:inline">Close</span>
            </button>
          </div>
        </div>
      </div>

      {showEnquiry && (
        <SupplierEnquiryModal
          theme={theme}
          supplierSlug={supplierSlug}
          sections={sections}
          totals={totals}
          getComponentById={getComponentById}
          grandTotal={grandTotal}
          allKeys={allKeys}
          unitSystem={unitSystem}
          currencySymbol={currencySymbol}
          onClose={() => setShowEnquiry(false)}
        />
      )}

      <style jsx global>{`
        @media print {
          @page { margin: 1cm; }
          html, body { background: white !important; margin: 0 !important; padding: 0 !important; }
          #takeoff-print { display: block !important; }
          header, footer, button { display: none !important; }
        }
      `}</style>
    </div>
  );
}
