'use client';

import { useState } from 'react';
import type { ThemeConfig, MeasureMode, UnitSystem, Entry, ComponentSection, RoofComponentDef, PitchType, TakeoffCapabilities } from '@roof-takeoff/core';
import { COMPONENT_DEFS, areaValueForUnit, computeEntry, isCustomFixed, makeId, componentLabel, componentDescription, ratioToDegrees, degreesToRatio } from '@roof-takeoff/core';
import { ComponentGuideBox } from '@roof-takeoff/ui';

// ─── Step Container ──────────────────────────────────

export function StepContainer({ title, subtitle, children, stepLabel }: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
  stepLabel?: string;
}) {
  return (
    <div className="animate-[fadeIn_0.3s_ease-out]">
      {stepLabel && <span className="text-xs font-medium text-slate-400 mb-2 block">{stepLabel}</span>}
      <h1 className="text-xl md:text-2xl font-semibold text-slate-900">{title}</h1>
      {subtitle && <p className="mt-2 text-sm text-slate-500">{subtitle}</p>}
      <div className="mt-6 md:mt-8">{children}</div>
    </div>
  );
}

// ─── Step Navigation ─────────────────────────────────

export function StepNav({ theme, onBack, onNext, nextLabel = 'Continue', nextDisabled = false, onSkip }: {
  theme: ThemeConfig;
  onBack: () => void;
  onNext: () => void;
  nextLabel?: string;
  nextDisabled?: boolean;
  onSkip?: () => void;
}) {
  return (
    <div className="mt-8 flex items-center justify-between gap-3">
      <button onClick={onBack} className="cursor-pointer rounded-lg px-4 py-2.5 text-sm font-medium text-slate-500 hover:text-slate-700 hover:bg-slate-50 transition min-h-[44px]">
        <svg className="w-4 h-4 inline mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" /></svg>
        Back
      </button>
      <div className="flex items-center gap-2">
        {onSkip && (
          <button onClick={onSkip} className="cursor-pointer rounded-lg px-4 py-2.5 text-sm font-medium text-slate-400 hover:text-slate-600 hover:bg-slate-50 transition min-h-[44px]">
            Skip
          </button>
        )}
        <button onClick={onNext} disabled={nextDisabled} className="cursor-pointer rounded-lg px-6 py-2.5 text-sm font-semibold text-white transition min-h-[44px]" style={nextDisabled ? { backgroundColor: '#e2e8f0', color: '#94a3b8', cursor: 'not-allowed' } : { backgroundColor: theme.primary }}>
          {nextLabel}
          <svg className="w-4 h-4 inline ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" /></svg>
        </button>
      </div>
    </div>
  );
}

// ─── Big Choice Card ─────────────────────────────────

export function BigChoiceCard({ theme, onClick, title, description, icon }: {
  theme: ThemeConfig;
  onClick: () => void;
  title: string;
  description: string;
  icon: 'check' | 'plan';
}) {
  return (
    <button onClick={onClick} className="w-full text-left rounded-2xl border-2 border-slate-200 bg-white p-5 md:p-6 transition-all cursor-pointer hover:shadow-lg group" onMouseEnter={(e) => { e.currentTarget.style.borderColor = theme.primary; e.currentTarget.style.boxShadow = `0 4px 20px ${theme.primary}15`; }} onMouseLeave={(e) => { e.currentTarget.style.borderColor = ''; e.currentTarget.style.boxShadow = ''; }}>
      <div className="flex items-start gap-4">
        <div className="w-12 h-12 rounded-full flex items-center justify-center flex-shrink-0" style={{ backgroundColor: theme.primary }}>
          {icon === 'check' ? (
            <svg className="w-7 h-7" viewBox="0 0 24 24" style={{ fill: '#ffffff' }}><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z" /></svg>
          ) : (
            <svg className="w-7 h-7" viewBox="0 0 24 24" style={{ fill: '#ffffff' }}><path d="M14 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z" /></svg>
          )}
        </div>
        <div className="flex-1 min-w-0">
          <h3 className="text-base md:text-lg font-semibold text-slate-900">{title}</h3>
          <p className="mt-1 text-sm text-slate-500">{description}</p>
        </div>
        <svg className="w-5 h-5 text-slate-300 group-hover:text-slate-400 transition flex-shrink-0 mt-1" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" /></svg>
      </div>
    </button>
  );
}

// ─── Pitch Input ─────────────────────────────────────

export function PitchInput({ theme, masterPitch, masterRatio, unitSystem, onUpdateDegrees, onUpdateRatio }: {
  theme: ThemeConfig;
  masterPitch: string;
  masterRatio: string;
  unitSystem: UnitSystem;
  onUpdateDegrees: (val: string) => void;
  onUpdateRatio: (val: string) => void;
}) {
  const [mode, setMode] = useState<'degrees' | 'ratio'>('degrees');
  const inputCls = "w-24 rounded-lg border border-slate-300 px-3 py-2 text-lg text-center focus:outline-none";

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <div className="flex items-center gap-1 rounded-full border border-slate-200 bg-white p-0.5 w-fit">
          <button onClick={() => setMode('degrees')} className="cursor-pointer rounded-full px-4 py-1.5 text-xs font-medium transition" style={mode === 'degrees' ? { backgroundColor: theme.primary, color: '#fff' } : { color: '#64748b' }}>Degrees</button>
          <button onClick={() => setMode('ratio')} className="cursor-pointer rounded-full px-4 py-1.5 text-xs font-medium transition" style={mode === 'ratio' ? { backgroundColor: theme.primary, color: '#fff' } : { color: '#64748b' }}>Ratio</button>
        </div>
      </div>
      <div className="flex items-center gap-3">
        {mode === 'degrees' ? (
          <>
            <div className="relative">
              <input type="number" value={masterPitch} onChange={(e) => onUpdateDegrees(e.target.value)} min={0} max={89} step={0.5} inputMode="decimal" className={inputCls} style={{ borderColor: theme.primary }} />
              <span className="absolute right-3 top-1/2 -translate-y-1/2 text-sm text-slate-400">deg</span>
            </div>
            <span className="text-sm text-slate-400">= {masterRatio}</span>
          </>
        ) : (
          <>
            <input type="text" value={masterRatio} onChange={(e) => onUpdateRatio(e.target.value)} placeholder="5:12" className={inputCls} style={{ borderColor: theme.primary }} />
            <span className="text-sm text-slate-400">= {masterPitch} deg</span>
          </>
        )}
      </div>
      <div className="rounded-xl bg-slate-50 border border-slate-100 p-3">
        <p className="text-xs text-slate-500">
          Common pitches: 15 deg (low pitch), 25 deg (standard UK), 35 deg (steep), 45 deg (very steep).
          {unitSystem === 'metric' ? ' Ratio format is rise:10 (e.g. 4.7:10).' : ' Ratio format is rise:12 (e.g. 5:12).'}
        </p>
      </div>
    </div>
  );
}

// ─── Component Step (one component per page) ─────────

export function ComponentStep({ theme, kind, section, measureMode, lenLbl, areaLbl, availableComponents, pitchDegrees, unitSystem, currencySymbol, total, roofAreaTotal, onAddEntry, onRemoveEntry, onUpdateWaste, stepNumber, totalSteps, onBack, onNext, nextLabel, capabilities }: {
  theme: ThemeConfig;
  kind: string;
  section: ComponentSection;
  measureMode: MeasureMode;
  lenLbl: string;
  areaLbl: string;
  availableComponents: RoofComponentDef[];
  pitchDegrees: number;
  unitSystem: UnitSystem;
  currencySymbol: string;
  total: { rawTotal: number; withWaste: number; count: number; totalCost: number };
  roofAreaTotal?: number | null;
  onAddEntry: (entry: Entry) => void;
  onRemoveEntry: (entryId: string) => void;
  onUpdateWaste: (waste: number) => void;
  stepNumber: number;
  totalSteps: number;
  onBack: () => void;
  onNext: () => void;
  capabilities?: TakeoffCapabilities;
  nextLabel?: string;
}) {
  const label = componentLabel(kind);
  const desc = componentDescription(kind);
  const isRoofArea = kind === 'roof_area' || kind === 'underlay' || kind === 'fixings';

  return (
    <div className="animate-[fadeIn_0.3s_ease-out]">
      <span className="text-xs font-medium text-slate-400 mb-2 block">Step {stepNumber} of {totalSteps}</span>
      <h1 className="text-xl md:text-2xl font-semibold text-slate-900">{label}</h1>
      <p className="mt-1.5 text-sm text-slate-500">{desc}</p>

      {/* Large guided visual - front and centre */}
      <div className="mt-4"><ComponentGuideBox componentKey={kind} highlightColor={theme.primary} measureMode={measureMode} /></div>

      {/* Inputs section */}
      <div className="mt-5">
        <div className="mb-3 flex items-center justify-between">
          <h3 className="text-sm font-semibold text-slate-900">Add measurements</h3>
          <div className="flex items-center gap-2">
            <label className="text-xs text-slate-500">Waste</label>
            <div className="relative">
              <input type="number" value={section.wastePercent} onChange={(e) => onUpdateWaste(parseFloat(e.target.value) || 0)} min={0} max={100} step={1} className="w-16 rounded-lg border border-slate-300 px-2 py-1 text-xs text-center focus:outline-none" style={{ borderColor: theme.primary }} />
              <span className="absolute right-1.5 top-1/2 -translate-y-1/2 text-[10px] text-slate-400">%</span>
            </div>
          </div>
        </div>

        <AddEntryForm theme={theme} kind={kind} measureMode={measureMode} lenLbl={lenLbl} areaLbl={areaLbl} availableComponents={availableComponents} pitchDegrees={pitchDegrees} unitSystem={unitSystem} currencySymbol={currencySymbol} roofAreaTotal={roofAreaTotal ?? null} onAdd={onAddEntry} capabilities={capabilities} />
      </div>

      {section.entries.length > 0 && (
        <div className="mt-4 space-y-2">
          <h3 className="text-sm font-semibold text-slate-900">Entries ({section.entries.length})</h3>
          {section.entries.map((entry, idx) => (
            <EntryRow key={entry.id} entry={entry} index={idx} kind={kind} measureMode={measureMode} lenLbl={lenLbl} areaLbl={areaLbl} wastePercent={section.wastePercent} onRemove={() => onRemoveEntry(entry.id)} />
          ))}
          {total.totalCost > 0 && (
            <div className="mt-2 rounded-lg border border-slate-200 bg-slate-50 px-4 py-2 flex items-center justify-between">
              <span className="text-xs text-slate-600">Subtotal (with waste)</span>
              <span className="text-sm font-semibold" style={{ color: theme.primary }}>{currencySymbol}{total.totalCost.toFixed(2)}</span>
            </div>
          )}
        </div>
      )}

      <StepNav theme={theme} onBack={onBack} onNext={onNext} nextLabel={nextLabel || 'Continue'} onSkip={onNext} />
    </div>
  );
}

// ─── Add Entry Form ──────────────────────────────────

function AddEntryForm({ theme, kind, measureMode, lenLbl, areaLbl, availableComponents, pitchDegrees, unitSystem, currencySymbol, roofAreaTotal, onAdd, capabilities }: {
  theme: ThemeConfig;
  kind: string;
  measureMode: MeasureMode;
  lenLbl: string;
  areaLbl: string;
  availableComponents: RoofComponentDef[];
  pitchDegrees: number;
  unitSystem: UnitSystem;
  currencySymbol: string;
  roofAreaTotal: number | null;
  onAdd: (entry: Entry) => void;
  capabilities?: TakeoffCapabilities;
}) {
  const pitchType = (COMPONENT_DEFS[kind]?.pitchType ?? 'none') as PitchType;
  const isRoofArea = kind === 'roof_area' || kind === 'underlay' || kind === 'fixings';
  const usePitch = measureMode === 'plan' && pitchType !== 'none';
  const planPrefix = measureMode === 'plan' ? 'Plan ' : '';

  const [areaMode, setAreaMode] = useState<'dimensions' | 'total'>(isRoofArea ? 'dimensions' : 'total');
  const [val1, setVal1] = useState('');
  const [val2, setVal2] = useState('');
  const [totalVal, setTotalVal] = useState('');
  const [quantity, setQuantity] = useState('1');
  const [label, setLabel] = useState('');
  const [selectedComponentId, setSelectedComponentId] = useState<string | null>(availableComponents[0]?.id ?? null);
  const [pricingMode, setPricingMode] = useState<'component' | 'known_price'>('component');
  const [knownPrice, setKnownPrice] = useState('');
  const canUseKnownPrice = capabilities?.knownPriceEntries ?? false;

  const resetForm = () => { setVal1(''); setVal2(''); setTotalVal(''); setQuantity('1'); setLabel(''); setKnownPrice(''); setPricingMode('component'); };

  const handleAdd = () => {
    let entry: Entry;
    const qty = parseInt(quantity) || 1;
    const kp = (canUseKnownPrice && pricingMode === 'known_price') ? parseFloat(knownPrice) : undefined;
    const compId = (canUseKnownPrice && pricingMode === 'known_price') ? null : selectedComponentId;

    if (isRoofArea) {
      if (areaMode === 'dimensions') {
        const w = parseFloat(val1); const l = parseFloat(val2);
        if (!w || w <= 0 || !l || l <= 0) return;
        entry = { id: makeId(), label, inputMode: usePitch ? 'pitch_calculated' : 'actual', planWidth: w, planLengthVal: l, pitchDegrees, actualValue: usePitch ? 0 : w * l, computedValue: 0, selectedComponentId: compId, quantity: qty, isTotalInput: false, knownPrice: kp };
      } else {
        const t = parseFloat(totalVal); if (!t || t <= 0) return;
        entry = { id: makeId(), label, inputMode: usePitch ? 'pitch_calculated' : 'actual', pitchDegrees, actualValue: t, computedValue: 0, selectedComponentId: compId, quantity: qty, isTotalInput: true, knownPrice: kp };
      }
    } else {
      const l = parseFloat(val1); if (!l || l <= 0) return;
      entry = { id: makeId(), label, inputMode: usePitch ? 'pitch_calculated' : 'actual', planLength: l, pitchDegrees, actualValue: usePitch ? 0 : l, computedValue: 0, selectedComponentId: compId, quantity: qty, isTotalInput: false, knownPrice: kp };
    }

    entry.computedValue = computeEntry(entry, kind, pitchType);
    if (isRoofArea) entry.computedValue = areaValueForUnit(entry.computedValue, unitSystem, areaMode === 'dimensions');
    onAdd(entry);
    resetForm();
  };

  const canAdd = isRoofArea ? (areaMode === 'dimensions' ? (parseFloat(val1) > 0 && parseFloat(val2) > 0) : parseFloat(totalVal) > 0) : parseFloat(val1) > 0;
  const canAddWithPrice = canAdd && (pricingMode === 'component' || (pricingMode === 'known_price' && parseFloat(knownPrice) > 0));
  const inputCls = "w-full rounded-lg border border-slate-300 px-3 py-2.5 text-base focus:outline-none";

  return (
    <div className="rounded-xl border border-slate-200 bg-slate-50/50 p-4 space-y-3">
      {isRoofArea && (
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1 rounded-full border border-slate-200 bg-white p-0.5 w-fit">
            <button onClick={() => setAreaMode('dimensions')} className="cursor-pointer rounded-full px-3 py-1 text-xs font-medium transition" style={areaMode === 'dimensions' ? { backgroundColor: theme.primary, color: '#fff' } : { color: '#64748b' }}>Width x Length</button>
            <button onClick={() => setAreaMode('total')} className="cursor-pointer rounded-full px-3 py-1 text-xs font-medium transition" style={areaMode === 'total' ? { backgroundColor: theme.primary, color: '#fff' } : { color: '#64748b' }}>Total Area</button>
          </div>
        </div>
      )}

      {isRoofArea && kind !== 'roof_area' && roofAreaTotal !== null && roofAreaTotal > 0 && (
        <div className="flex items-center gap-1.5">
          <button onClick={() => { setAreaMode('total'); setTotalVal(roofAreaTotal.toFixed(2)); }} className="cursor-pointer rounded-lg px-3 py-1.5 text-xs font-medium text-white transition" style={{ backgroundColor: theme.primary }}>Use Roof Area ({roofAreaTotal.toFixed(2)} {areaLbl})</button>
          <div className="relative group flex-shrink-0">
            <span className="cursor-help inline-flex items-center justify-center w-4 h-4 rounded-full border border-slate-300 text-slate-400 text-[10px] font-bold">?</span>
            <div className="absolute left-1/2 -translate-x-1/2 bottom-full mb-1.5 w-48 rounded-lg bg-slate-800 text-white text-xs px-3 py-2 opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity z-10">This automatically applies the total roof area you added in step 1</div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-2 gap-3">
        {isRoofArea && areaMode === 'dimensions' ? (
          <>
            <div><label className="text-xs font-medium text-slate-600">{planPrefix}Width ({lenLbl})</label><input type="number" value={val1} onChange={(e) => setVal1(e.target.value)} min={0} step="any" inputMode="decimal" placeholder="0" className={inputCls} style={{ borderColor: theme.primary }} /></div>
            <div><label className="text-xs font-medium text-slate-600">{planPrefix}Length ({lenLbl})</label><input type="number" value={val2} onChange={(e) => setVal2(e.target.value)} min={0} step="any" inputMode="decimal" placeholder="0" className={inputCls} style={{ borderColor: theme.primary }} /></div>
          </>
        ) : isRoofArea && areaMode === 'total' ? (
          <div className="col-span-2"><label className="text-xs font-medium text-slate-600">{planPrefix}Area ({areaLbl})</label><input type="number" value={totalVal} onChange={(e) => setTotalVal(e.target.value)} min={0} step="any" inputMode="decimal" placeholder="0" className={inputCls} style={{ borderColor: theme.primary }} /></div>
        ) : (
          <div className="col-span-2"><label className="text-xs font-medium text-slate-600">{planPrefix}Length ({lenLbl})</label><input type="number" value={val1} onChange={(e) => setVal1(e.target.value)} min={0} step="any" inputMode="decimal" placeholder="0" className={inputCls} style={{ borderColor: theme.primary }} /></div>
        )}
      </div>

      {/* Pricing mode toggle: component vs known price */}
      {canUseKnownPrice && availableComponents.length > 0 && (
        <div className="flex items-center gap-1 rounded-full border border-slate-200 bg-white p-0.5 w-fit">
          <button onClick={() => setPricingMode('component')} className="cursor-pointer rounded-full px-3 py-1 text-xs font-medium transition" style={pricingMode === 'component' ? { backgroundColor: theme.primary, color: '#fff' } : { color: '#64748b' }}>Select Product</button>
          <button onClick={() => setPricingMode('known_price')} className="cursor-pointer rounded-full px-3 py-1 text-xs font-medium transition" style={pricingMode === 'known_price' ? { backgroundColor: theme.primary, color: '#fff' } : { color: '#64748b' }}>Known Price</button>
        </div>
      )}

      {/* Component dropdown OR known price input */}
      {pricingMode === 'component' && availableComponents.length > 0 && (
        <div>
          <label className="text-xs font-medium text-slate-600">Product</label>
          <select value={selectedComponentId || ''} onChange={(e) => setSelectedComponentId(e.target.value || null)} className="mt-0.5 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-700 focus:outline-none cursor-pointer" style={{ borderColor: theme.primary }}>
            <option value="">- No product (measurements only) -</option>
            {availableComponents.map(comp => (<option key={comp.id} value={comp.id}>{comp.name} ({currencySymbol}{comp.price_per_unit.toFixed(2)}/{comp.unit})</option>))}
          </select>
        </div>
      )}
      {canUseKnownPrice && pricingMode === 'known_price' && (
        <div>
          <label className="text-xs font-medium text-slate-600">Price per {isRoofArea ? areaLbl : lenLbl}</label>
          <input type="number" value={knownPrice} onChange={(e) => setKnownPrice(e.target.value)} min={0} step="any" inputMode="decimal" placeholder="0.00" className={inputCls} style={{ borderColor: theme.primary }} />
        </div>
      )}
      {pricingMode === 'component' && availableComponents.length === 0 && !canUseKnownPrice && (
        <p className="text-xs text-slate-400">No components available for this section.</p>
      )}
      {canUseKnownPrice && pricingMode === 'known_price' && availableComponents.length === 0 && (
        <p className="text-xs text-slate-400">Enter your own price per {isRoofArea ? areaLbl : lenLbl}.</p>
      )}

      <input type="text" value={label} onChange={(e) => setLabel(e.target.value)} placeholder="Optional label (e.g. Front gable, Main roof)" className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm text-slate-600 focus:outline-none" />

      <div className="grid grid-cols-2 gap-3">
        <div><label className="text-xs font-medium text-slate-600">Quantity</label><input type="number" value={quantity} onChange={(e) => setQuantity(e.target.value)} min={1} step={1} inputMode="numeric" className={inputCls} /></div>
        <div className="flex items-end">
          <button onClick={handleAdd} disabled={!canAddWithPrice} className="w-full cursor-pointer rounded-lg px-4 py-2.5 text-sm font-semibold text-white transition min-h-[44px]" style={canAddWithPrice ? { backgroundColor: theme.primary } : { backgroundColor: '#e2e8f0', color: '#94a3b8', cursor: 'not-allowed' }}>Add Entry</button>
        </div>
      </div>
    </div>
  );
}

// ─── Entry Row ───────────────────────────────────────

function EntryRow({ entry, index, kind, measureMode, lenLbl, areaLbl, wastePercent, onRemove }: {
  entry: Entry;
  index: number;
  kind: string;
  measureMode: MeasureMode;
  lenLbl: string;
  areaLbl: string;
  wastePercent: number;
  onRemove: () => void;
}) {
  const isRoofArea = kind === 'roof_area' || kind === 'underlay' || kind === 'fixings';
  const isFixed = kind.startsWith('custom-') && isCustomFixed(kind);
  const unit = isFixed ? 'pcs' : isRoofArea ? areaLbl : lenLbl;
  const usePitch = measureMode === 'plan' && entry.inputMode === 'pitch_calculated';
  const inputDesc = isFixed ? `Qty: ${entry.quantity ?? 1}` : entry.isTotalInput ? `Total: ${entry.actualValue ?? 0}` : isRoofArea ? `${entry.planWidth ?? 0} x ${entry.planLengthVal ?? 0}` : `${entry.planLength ?? entry.actualValue ?? 0}`;

  return (
    <div className="flex items-center justify-between rounded-xl border border-slate-200 bg-white px-4 py-3 transition hover:border-slate-300">
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <span className="text-sm font-medium text-slate-700">{entry.label || `Entry ${index + 1}`}</span>
          {usePitch && <span className="text-xs text-slate-400">@ {entry.pitchDegrees} deg</span>}
          {entry.quantity && entry.quantity > 1 && <span className="text-xs text-slate-400">x{entry.quantity}</span>}
        </div>
        <div className="flex items-center gap-2 mt-0.5 flex-wrap">
          <span className="text-xs text-slate-400">{inputDesc}</span>
          {usePitch && <span className="text-xs text-slate-300">-&gt;</span>}
          <span className="text-xs text-slate-500">{entry.computedValue.toFixed(2)} {unit}</span>
          {wastePercent > 0 && <span className="text-xs text-slate-400">+{wastePercent}% = {(entry.computedValue * (1 + wastePercent / 100)).toFixed(2)}</span>}
        </div>
        {entry.knownPrice != null && entry.knownPrice > 0 && (
          <div className="mt-0.5"><span className="text-xs text-slate-500">Known price</span> <span className="text-xs font-medium" style={{ color: '#BD4A1A' }}>{entry.knownPrice.toFixed(2)}/{isFixed ? 'pc' : isRoofArea ? areaLbl : lenLbl}</span></div>
        )}
      </div>
      <button onClick={onRemove} className="text-slate-300 hover:text-red-500 transition p-1 cursor-pointer" aria-label="Remove entry">
        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
      </button>
    </div>
  );
}

// ─── Review Step ─────────────────────────────────────

export function ReviewStep({ theme, sections, totals, allKeys, lenLbl, areaLbl, cur, grandTotal, hasData, stepNumber, totalSteps, onBack, onGenerate, onRemoveEntry }: {
  theme: ThemeConfig;
  sections: Record<string, ComponentSection>;
  totals: Record<string, { rawTotal: number; withWaste: number; count: number; materialCost: number; labourCost: number; totalCost: number }>;
  allKeys: string[];
  lenLbl: string;
  areaLbl: string;
  cur: string;
  grandTotal: number;
  hasData: boolean;
  stepNumber: number;
  totalSteps: number;
  onBack: () => void;
  onGenerate: () => void;
  onRemoveEntry: (key: string, entryId: string) => void;
}) {
  return (
    <div className="animate-[fadeIn_0.3s_ease-out]">
      <span className="text-xs font-medium text-slate-400 mb-2 block">Step {stepNumber} of {totalSteps}</span>
      <h1 className="text-xl md:text-2xl font-semibold text-slate-900">Review your takeoff</h1>
      <p className="mt-2 text-sm text-slate-500">Check your measurements below. If everything looks correct, generate your takeoff report.</p>

      {hasData ? (
        <div className="mt-6 space-y-4">
          {allKeys.map(key => {
            const section = sections[key];
            if (!section || section.entries.length === 0) return null;
            const t = totals[key];
            if (!t) return null;
            const isArea = key === 'roof_area' || key === 'underlay' || key === 'fixings';
            const unit = isArea ? areaLbl : lenLbl;
            const label = componentLabel(key);

            return (
              <div key={key} className="rounded-xl border border-slate-200 bg-white p-4">
                <div className="flex items-center justify-between mb-2">
                  <h3 className="text-sm font-semibold text-slate-900">{label}</h3>
                  <span className="text-xs text-slate-400">{t.count} {t.count === 1 ? 'entry' : 'entries'}</span>
                </div>
                <div className="space-y-1">
                  {section.entries.map((entry, idx) => (
                    <div key={entry.id} className="flex items-center justify-between text-xs">
                      <span className="text-slate-500">{entry.label || `Entry ${idx + 1}`}</span>
                      <span className="text-slate-700 font-medium">{entry.computedValue.toFixed(2)} {unit}</span>
                    </div>
                  ))}
                </div>
                <div className="mt-2 pt-2 border-t border-slate-100 flex items-center justify-between">
                  <span className="text-xs text-slate-400">Subtotal{section.wastePercent > 0 ? ` (+${section.wastePercent}% waste)` : ''}</span>
                  <span className="text-sm font-semibold text-slate-900">{t.withWaste.toFixed(2)} {unit}</span>
                </div>
                {t.totalCost > 0 && (
                  <div className="flex items-center justify-between mt-1">
                    <span className="text-xs text-slate-400">Cost</span>
                    <span className="text-sm font-semibold" style={{ color: theme.primary }}>{cur}{t.totalCost.toFixed(2)}</span>
                  </div>
                )}
              </div>
            );
          })}

          {grandTotal > 0 && (
            <div className="rounded-xl bg-slate-900 text-white p-4 flex items-center justify-between">
              <span className="text-sm font-semibold">Estimated Total</span>
              <span className="text-xl font-bold">{cur}{grandTotal.toFixed(2)}</span>
            </div>
          )}

          <button onClick={onGenerate} className="w-full cursor-pointer rounded-lg px-6 py-3 text-sm font-semibold text-white transition min-h-[44px]" style={{ backgroundColor: theme.primary }}>
            Generate Takeoff Report
            <svg className="w-4 h-4 inline ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" /></svg>
          </button>

          <button onClick={onBack} className="cursor-pointer rounded-lg px-4 py-2.5 text-sm font-medium text-slate-500 hover:text-slate-700 hover:bg-slate-50 transition min-h-[44px] w-full text-center mt-2">
            <svg className="w-4 h-4 inline mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" /></svg>
            Back
          </button>
        </div>
      ) : (
        <div className="mt-6 rounded-xl border-dashed border border-slate-200 px-6 py-12 text-center">
          <p className="text-sm text-slate-500">No measurements added yet.</p>
          <p className="mt-1 text-xs text-slate-400">Go back and add your roof measurements to generate a report.</p>
        </div>
      )}

      {/* No step nav on review - Generate button is the primary action */}
    </div>
  );
}
