'use client';

import { useState } from 'react';

interface ComponentGuideBoxProps {
  componentKey: string;
  highlightColor: string;
  measureMode?: 'plan' | 'actual';
}

const GUIDE_CONTENT: Record<string, { label: string; instruction: string | ((mode: 'plan' | 'actual') => string); diagram: string; tip: string }> = {
  roof_area: {
    label: 'Roof Area',
    instruction: (mode) => mode === 'plan'
      ? 'Measure entire roof outline. Enter plan dimensions (width x length) or total area and we will calculate the sloped area using your roof pitch.'
      : 'Measure entire roof outline. Enter plan dimensions (width x length) or total area.',
    diagram: 'The entire roof outline is highlighted. This is the surface area of all roof planes.',
    tip: 'If you have a plan view, enter the flat dimensions. The pitch factor is applied automatically.',
  },
  ridge: {
    label: 'Ridge',
    instruction: 'Measure the horizontal/vertical peaks where two roof slopes meet.',
    diagram: 'The horizontal lines at the top of each roof section are highlighted.',
    tip: 'Ridges are always horizontal. If a line slopes downward, it is a hip or barge, not a ridge.',
  },
  hip: {
    label: 'Hip',
    instruction: 'Measure all the angled lines where 2 roof faces meet (Exclude valleys, which start from internal corners of the roof outline, they are the next step.)',
    diagram: 'The diagonal lines from the ridge to the external corners are highlighted.',
    tip: 'Hips run from the ridge to an external corner. Valleys look similar but are internal corners.',
  },
  valley: {
    label: 'Valley',
    instruction: 'Measure the angled lines where two roof planes meet and water flows into, they normally always end on an internal corner of the roof outline.',
    diagram: 'The inward diagonal lines where roof sections join are highlighted.',
    tip: 'Valleys collect water. If a line runs to an external corner, it is a hip, not a valley.',
  },
  barge: {
    label: 'Barge',
    instruction: 'Measure the barge/rake sections that run parallel to the roof outline. These areas normally have no spouting, and run in the same direction that water flows on the outline of the roof.',
    diagram: 'The sloped edges at the gable ends are highlighted.',
    tip: 'Barges are the diagonal edges at the side of a gable. Also called rake or verge.',
  },
  spouting: {
    label: 'Spouting',
    instruction: 'Measure the lower roof outline where gutters will be installed - Not including barge/rake sections.',
    diagram: 'The perimeter edges at the bottom of the roof are highlighted.',
    tip: 'Spouting runs along the bottom edge (eaves). Do not include gable edges.',
  },
  underlay: {
    label: 'Underlay',
    instruction: 'Uses the total roof area. Underlay covers the entire roof surface beneath the main covering.',
    diagram: 'The entire roof outline is highlighted, same as roof area.',
    tip: 'Underlay area matches your roof area. You can use the Roof Area total directly.',
  },
  fixings: {
    label: 'Fixings',
    instruction: 'Uses the total roof area to calculate nails, screws, or clips needed.',
    diagram: 'The entire roof outline is highlighted, same as roof area.',
    tip: 'Fixings are calculated per area. You can use the Roof Area total directly.',
  },
};

function getInstruction(componentKey: string, mode: 'plan' | 'actual'): string {
  const content = GUIDE_CONTENT[componentKey];
  if (!content) return '';
  return typeof content.instruction === 'function' ? content.instruction(mode) : content.instruction;
}

// ─── Large component symbol (left panel) ─────────────
// Uses the exact same SVG paths as the QuoteCore+ accordion ComponentSymbol

function ComponentSymbol({ componentKey, color }: { componentKey: string; color: string }) {
  const sw = 2.5;
  const cls = "h-16 w-16 sm:h-20 sm:w-20";

  switch (componentKey) {
    case 'roof_area':
      return (
        <svg className={cls} fill="none" viewBox="0 0 24 24" stroke={color} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M3 12l9-9 9 9M5 10v10h14V10" />
        </svg>
      );
    case 'ridge':
      return (
        <svg className={cls} fill="none" viewBox="0 0 24 24" stroke={color} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M4 20L12 6l8 14" />
        </svg>
      );
    case 'hip':
      return (
        <svg className={cls} fill="none" viewBox="0 0 24 24" stroke={color} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M4 20L12 6l8 14" />
        </svg>
      );
    case 'valley':
      return (
        <svg className={cls} fill="none" viewBox="0 0 24 24" stroke={color} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M4 6l8 14 8-14" />
        </svg>
      );
    case 'barge':
      return (
        <svg className={cls} fill="none" viewBox="0 0 24 24" stroke={color} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M5 20V4h14" />
        </svg>
      );
    case 'spouting':
      return (
        <svg className={cls} fill="none" viewBox="0 0 24 24" stroke={color} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M4 8v3a2 2 0 002 2h12a2 2 0 002-2V8" />
        </svg>
      );
    case 'underlay':
      return (
        <svg className={cls} fill="none" viewBox="0 0 24 24" stroke={color} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M3 8l9-5 9 5-9 5-9-5z" />
          <path strokeLinecap="round" strokeLinejoin="round" d="M3 12l9 5 9-5" />
          <path strokeLinecap="round" strokeLinejoin="round" d="M3 16l9 5 9-5" />
        </svg>
      );
    case 'fixings':
      return (
        <svg className={cls} fill="none" viewBox="0 0 24 24" stroke={color} strokeWidth={sw}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M8 4h8M12 4v16M9 20l3-2 3 2" />
        </svg>
      );
    default:
      return null;
  }
}

// ─── Info tooltip ────────────────────────────────────

function InfoTooltip({ text, color }: { text: string; color: string }) {
  const [open, setOpen] = useState(false);
  return (
    <span className="relative inline-flex">
      <button
        type="button"
        aria-label={text}
        onClick={() => setOpen(o => !o)}
        onMouseEnter={() => setOpen(true)}
        onMouseLeave={() => setOpen(false)}
        onFocus={() => setOpen(true)}
        onBlur={() => setOpen(false)}
        className="flex h-5 w-5 cursor-help items-center justify-center rounded-full border text-[10px] font-bold leading-none transition hover:scale-110"
        style={{ borderColor: `${color}55`, color, backgroundColor: `${color}08` }}
      >
        i
      </button>
      {open && (
        <span
          role="tooltip"
          className="absolute bottom-full left-1/2 z-50 mb-2 w-60 -translate-x-1/2 rounded-lg bg-slate-900 px-3 py-2 text-center text-xs font-normal leading-relaxed text-white shadow-xl"
        >
          {text}
        </span>
      )}
    </span>
  );
}

// ─── Large roof plan SVG (right panel) ───────────────

function GuideSVG({ componentKey, highlightColor }: { componentKey: string; highlightColor: string }) {
  const black = '#94a3b8';
  const sw = 2;
  const ow = 6;

  const outline = 'M 40 40 L 420 40 L 420 280 L 320 280 L 320 340 L 140 340 L 140 280 L 40 280 Z';
  const mainRidge = <line x1="160" y1="160" x2="300" y2="160" />;
  const dormerRidge = <line x1="230" y1="340" x2="230" y2="190" />;
  const hips = [
    <line key="h1" x1="160" y1="160" x2="40" y2="40" />,
    <line key="h2" x1="160" y1="160" x2="40" y2="280" />,
    <line key="h3" x1="300" y1="160" x2="420" y2="40" />,
    <line key="h4" x1="300" y1="160" x2="420" y2="280" />,
  ];
  const valleys = [
    <line key="v1" x1="140" y1="280" x2="230" y2="190" />,
    <line key="v2" x1="320" y1="280" x2="230" y2="190" />,
  ];
  const barges = [
    <line key="b1" x1="140" y1="340" x2="230" y2="340" />,
    <line key="b2" x1="230" y1="340" x2="320" y2="340" />,
  ];
  const allInternal = (
    <>
      {mainRidge}
      {dormerRidge}
      {hips}
      {valleys}
      {barges}
    </>
  );

  let highlightElements: React.ReactNode = null;
  let blackElements: React.ReactNode = allInternal;
  let outlineColor = black;
  let outlineWidth = sw;

  switch (componentKey) {
    case 'roof_area':
    case 'underlay':
    case 'fixings':
      outlineColor = highlightColor;
      outlineWidth = ow;
      blackElements = allInternal;
      break;
    case 'ridge':
      highlightElements = (
        <>
          {mainRidge}
          {dormerRidge}
        </>
      );
      blackElements = (
        <>
          {hips}
          {valleys}
          {barges}
        </>
      );
      break;
    case 'hip':
      highlightElements = <>{hips}</>;
      blackElements = (
        <>
          {mainRidge}
          {dormerRidge}
          {valleys}
          {barges}
        </>
      );
      break;
    case 'valley':
      highlightElements = <>{valleys}</>;
      blackElements = (
        <>
          {mainRidge}
          {dormerRidge}
          {hips}
          {barges}
        </>
      );
      break;
    case 'barge':
      highlightElements = <>{barges}</>;
      blackElements = (
        <>
          {mainRidge}
          {dormerRidge}
          {hips}
          {valleys}
        </>
      );
      break;
    case 'spouting':
      outlineColor = black;
      outlineWidth = sw;
      highlightElements = (
        <>
          <line x1="40" y1="40" x2="420" y2="40" stroke={highlightColor} strokeWidth={ow} strokeLinecap="round" />
          <line x1="40" y1="40" x2="40" y2="280" stroke={highlightColor} strokeWidth={ow} strokeLinecap="round" />
          <line x1="420" y1="40" x2="420" y2="280" stroke={highlightColor} strokeWidth={ow} strokeLinecap="round" />
          <line x1="40" y1="280" x2="140" y2="280" stroke={highlightColor} strokeWidth={ow} strokeLinecap="round" />
          <line x1="320" y1="280" x2="420" y2="280" stroke={highlightColor} strokeWidth={ow} strokeLinecap="round" />
          <line x1="140" y1="280" x2="140" y2="340" stroke={highlightColor} strokeWidth={ow} strokeLinecap="round" />
          <line x1="320" y1="280" x2="320" y2="340" stroke={highlightColor} strokeWidth={ow} strokeLinecap="round" />
        </>
      );
      blackElements = allInternal;
      break;
  }

  return (
    <svg viewBox="0 0 460 380" className="h-auto w-full" style={{ maxHeight: '260px' }} aria-hidden="true">
      <defs>
        <pattern id={`grid-${componentKey}`} width="20" height="20" patternUnits="userSpaceOnUse">
          <path d="M 20 0 L 0 0 0 20" fill="none" stroke="#f1f5f9" strokeWidth="0.5" />
        </pattern>
      </defs>
      <rect width="460" height="380" fill={`url(#grid-${componentKey})`} />
      <path d={outline} fill="none" stroke={outlineColor} strokeWidth={outlineWidth} strokeLinecap="round" strokeLinejoin="round" />
      <g fill="none" stroke={black} strokeWidth={sw} strokeLinecap="round" strokeLinejoin="round" opacity="0.4">
        {blackElements}
      </g>
      {highlightElements && componentKey !== 'spouting' && (
        <g fill="none" stroke={highlightColor} strokeWidth={ow} strokeLinecap="round">
          {highlightElements}
        </g>
      )}
      {componentKey === 'spouting' && highlightElements}
    </svg>
  );
}

// ─── Main exported component ─────────────────────────

export function ComponentGuideBox({ componentKey, highlightColor, measureMode = 'plan' }: ComponentGuideBoxProps) {
  const content = GUIDE_CONTENT[componentKey];
  if (!content) return null;

  const isArea = componentKey === 'roof_area' || componentKey === 'underlay' || componentKey === 'fixings';
  const instruction = getInstruction(componentKey, measureMode);

  return (
    <section
      className="rounded-2xl border bg-white shadow-sm"
      style={{ borderColor: `${highlightColor}30` }}
      aria-label={`${content.label} visual guide`}
    >
      {/* Header bar */}
      <div
        className="relative flex items-center justify-between border-b px-4 py-2.5 sm:px-5"
        style={{ borderColor: `${highlightColor}20`, backgroundColor: `${highlightColor}06` }}
      >
        <div className="flex items-center gap-2">
          <span
            className="text-[10px] font-bold uppercase tracking-[0.18em]"
            style={{ color: highlightColor }}
          >
            Guided
          </span>
          <span className="text-slate-300">|</span>
          <span className="text-xs font-medium text-slate-500">
            {isArea ? 'Covers entire roof area' : 'Highlighted on roof plan'}
          </span>
        </div>
        <InfoTooltip text={content.tip} color={highlightColor} />
      </div>

      {/* Two-column visual layout */}
      <div className="grid grid-cols-1 sm:grid-cols-[auto_1fr]">
        {/* Left: Large component symbol */}
        <div
          className="flex flex-col items-center justify-center px-6 py-6 sm:border-r"
          style={{ borderColor: `${highlightColor}20`, backgroundColor: `${highlightColor}05` }}
        >
          <div
            className="flex h-28 w-28 items-center justify-center rounded-2xl bg-white shadow-sm sm:h-32 sm:w-32"
            style={{
              boxShadow: `0 8px 30px ${highlightColor}15, 0 0 0 1px ${highlightColor}20`,
            }}
          >
            <ComponentSymbol componentKey={componentKey} color={highlightColor} />
          </div>
          <p className="mt-3 text-sm font-bold text-slate-900">{content.label}</p>
        </div>

        {/* Right: Large roof plan with highlighted component */}
        <div className="flex flex-col items-center justify-center px-4 py-5">
          <div className="w-full max-w-md">
            <GuideSVG componentKey={componentKey} highlightColor={highlightColor} />
          </div>
          <div className="mt-2 flex items-center gap-2">
            <span
              className="inline-block h-1.5 w-6 rounded-full"
              style={{ backgroundColor: highlightColor }}
            />
            <span className="text-xs font-medium text-slate-600">
              {isArea ? 'Entire roof area highlighted' : `${content.label} highlighted on plan`}
            </span>
            <InfoTooltip text={content.diagram} color={highlightColor} />
          </div>
        </div>
      </div>

      {/* Instruction bar */}
      <div
        className="border-t px-4 py-2.5 sm:px-5"
        style={{ borderColor: `${highlightColor}15`, backgroundColor: `${highlightColor}04` }}
      >
        <p className="text-xs leading-relaxed text-slate-600">
          <span className="font-semibold" style={{ color: highlightColor }}>
            {content.label}:
          </span>{' '}
          {instruction}
        </p>
      </div>
    </section>
  );
}
