'use client';

import { useState, useMemo, useCallback, useEffect, type CSSProperties } from 'react';
import Link from 'next/link';
import type {
  ThemeConfig,
  MeasureMode,
  UnitSystem,
  Entry,
  ComponentSection,
  RoofComponentDef,
  PitchType,
  PricingMode,
  LayoutChoice,
  TakeoffCapabilities,
  TakeoffPrefill,
} from '@roof-takeoff/core';
import {
  COMPONENT_DEFS,
  BUILT_IN_ORDER,
  areaValueForUnit,
  entriesFromPrefillValues,
  computeEntry,
  makeInitialSections,
  makeId,
  calculateTakeoffSections,
  unitLabel,
  areaUnitLabel,
  ratioToDegrees,
  degreesToRatio,
  componentLabel,
  componentDescription,
} from '@roof-takeoff/core';
import { ComponentGuideBox, ResultsModal } from '@roof-takeoff/ui';
import { StepNav, BigChoiceCard, PitchInput, ComponentStep, StepContainer } from './components';

const COMPONENT_STEPS = BUILT_IN_ORDER.filter(k => k !== 'roof_area');

interface FormsLayoutProps {
  theme: ThemeConfig;
  components: RoofComponentDef[];
  initialMeasureMode?: MeasureMode | null;
  pricingMode?: PricingMode | null;
  onSwitchLayout?: (choice: LayoutChoice) => void;
  capabilities?: TakeoffCapabilities;
  prefill?: TakeoffPrefill | null;
}

export function FormsLayout({ theme, components, initialMeasureMode = null, pricingMode = null, onSwitchLayout, capabilities, prefill = null }: FormsLayoutProps) {
  const [measureMode, setMeasureMode] = useState<MeasureMode | null>(prefill?.measureMode ?? initialMeasureMode);
  const [step, setStep] = useState((prefill?.measureMode ?? initialMeasureMode) ? 1 : 0);
  const [masterPitch, setMasterPitch] = useState('25');
  const [masterRatio, setMasterRatio] = useState('5:12');
  const [sections, setSections] = useState<Record<string, ComponentSection>>(makeInitialSections);
  const [customSections, setCustomSections] = useState<Record<string, ComponentSection>>({});
  const [showResults, setShowResults] = useState(false);
  const [prefillApplied, setPrefillApplied] = useState(!prefill);

  const u = theme.defaultUnits;
  const lenLbl = unitLabel(u);
  const areaLbl = areaUnitLabel(u);
  const cur = theme.currencySymbol;

  const componentsByKind = useMemo(() => {
    const map: Record<string, RoofComponentDef[]> = {};
    for (const kind of BUILT_IN_ORDER) {
      map[kind] = components.filter(c => c.component_kind === kind);
    }
    return map;
  }, [components]);

  const getComponentById = useCallback((id: string | null): RoofComponentDef | null => {
    if (!id) return null;
    return components.find(c => c.id === id) ?? null;
  }, [components]);

  const effectivePitch = parseFloat(masterPitch) || 0;

  useEffect(() => {
    if (measureMode !== 'plan') return;
    const recalculate = (current: Record<string, ComponentSection>) => {
      let changed = false;
      const next: Record<string, ComponentSection> = {};
      for (const [key, section] of Object.entries(current)) {
        const pitchType = section.customDef?.pitchType ?? COMPONENT_DEFS[key]?.pitchType ?? 'none';
        const isArea = key === 'roof_area' || key === 'underlay' || key === 'fixings' || section.customDef?.measurementType === 'area';
        const entries = section.entries.map(entry => {
          if (entry.inputMode !== 'pitch_calculated') return entry;
          const updated = { ...entry, pitchDegrees: effectivePitch };
          let cv = computeEntry(updated, key, pitchType);
          if (isArea) cv = areaValueForUnit(cv, u, !entry.isTotalInput);
          changed = changed || cv !== entry.computedValue || entry.pitchDegrees !== effectivePitch;
          return { ...updated, computedValue: cv };
        });
        next[key] = { ...section, entries };
      }
      return changed ? next : current;
    };
    setSections(recalculate);
    setCustomSections(recalculate);
  }, [effectivePitch, measureMode, u]);

  const allSections = useMemo(() => ({ ...sections, ...customSections }), [sections, customSections]);
  const allKeys = useMemo(() => [...BUILT_IN_ORDER, ...Object.keys(customSections)], [customSections]);

  const showLabour = pricingMode !== 'material';

  const calculation = useMemo(
    () => calculateTakeoffSections(allSections, allKeys, getComponentById, showLabour),
    [allSections, allKeys, getComponentById, showLabour],
  );
  const totals = calculation.sections;
  const hasData = calculation.totalEntries > 0;
  const grandTotal = showLabour ? calculation.grandTotal : calculation.materialTotal;

  const addEntry = (key: string, entry: Entry) => {
    const setter = key.startsWith('custom-') ? setCustomSections : setSections;
    setter(prev => ({ ...prev, [key]: { ...prev[key], entries: [...prev[key].entries, entry] } }));
  };
  const removeEntry = (key: string, entryId: string) => {
    const setter = key.startsWith('custom-') ? setCustomSections : setSections;
    setter(prev => ({ ...prev, [key]: { ...prev[key], entries: prev[key].entries.filter(e => e.id !== entryId) } }));
  };
  const updateWaste = (key: string, waste: number) => {
    const setter = key.startsWith('custom-') ? setCustomSections : setSections;
    setter(prev => ({ ...prev, [key]: { ...prev[key], wastePercent: waste } }));
  };

  const totalSteps = measureMode === 'plan' ? 2 + COMPONENT_STEPS.length : 1 + COMPONENT_STEPS.length;
  const roofAreaStep = measureMode === 'plan' ? 2 : 1;
  const lastComponentStep = measureMode === 'plan' ? 2 + COMPONENT_STEPS.length : 1 + COMPONENT_STEPS.length;
  const stepIndex = Math.min(step, lastComponentStep);
  const progress = ((stepIndex + 1) / totalSteps) * 100;

  const handleNext = () => {
    if (step >= lastComponentStep) {
      setShowResults(true);
    } else {
      setStep(s => Math.min(s + 1, lastComponentStep));
    }
  };
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  // Scroll to top on step change
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [step]);

  const startOver = () => {
    setSections(makeInitialSections());
    setCustomSections({});
    setMasterPitch('25');
    setMasterRatio('5:12');
    setMeasureMode(null);
    setStep(0);
    setShowResults(false);
  };

  const updatePitchDegrees = (val: string) => {
    setMasterPitch(val);
    const deg = parseFloat(val) || 0;
    setMasterRatio(degreesToRatio(deg, u));
  };

  // Apply prefilled measurements once on mount (AI-agent / shared-link flow)
  useEffect(() => {
    if (!prefill || prefillApplied) return;
    const pitch = prefill.pitchDegrees;
    if (typeof pitch === 'number' && pitch > 0 && Number.isFinite(pitch)) {
      setMasterPitch(String(pitch));
      setMasterRatio(degreesToRatio(pitch, u));
    }
    setSections(prev => {
      const next = { ...prev };
      const entriesByKind = entriesFromPrefillValues(prefill.values, prefill.measureMode, typeof pitch === 'number' ? pitch : parseFloat(masterPitch) || 0, u);
      for (const [k, entries] of Object.entries(entriesByKind)) {
        if (next[k]) next[k] = { ...next[k], entries };
      }
      if (prefill.wastePercent) {
        for (const [k, w] of Object.entries(prefill.wastePercent)) {
          if (next[k]) next[k] = { ...next[k], wastePercent: w };
        }
      }
      return next;
    });
    setPrefillApplied(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [prefill, prefillApplied]);

  return (
    <main
      className="roof-takeoff-theme min-h-screen bg-white flex flex-col"
      style={{ fontFamily: theme.bodyFont, '--roof-heading-font': theme.headingFont } as CSSProperties}
    >
      <header className="border-b border-slate-100 sticky top-0 z-10 bg-white/95 backdrop-blur-sm">
        <div className="mx-auto max-w-2xl px-4 py-3 flex items-center justify-between">
          <Link href="/" className="flex items-center">
            {theme.logoUrl ? (
              <img src={theme.logoUrl} alt={theme.supplierName ?? undefined} className="h-8 md:h-10 w-auto" />
            ) : (
              <span className="text-sm font-semibold text-slate-900">{theme.copy.headerTitle}</span>
            )}
          </Link>
          <div className="flex items-center gap-3">
            {onSwitchLayout && (
              <button onClick={() => onSwitchLayout('fast')} className="cursor-pointer rounded-full border border-slate-200 px-3 py-1 text-xs font-medium text-slate-500 hover:text-slate-700 hover:border-slate-300 transition">
                Fast mode
              </button>
            )}
            {theme.copy.poweredBy && (
              <span className="text-xs text-slate-400">{theme.copy.poweredBy}</span>
            )}
          </div>
        </div>
        {measureMode && !showResults && (
          <div className="h-1 bg-slate-100">
            <div className="h-full transition-all duration-300 ease-out" style={{ width: `${progress}%`, backgroundColor: theme.primary }} />
          </div>
        )}
      </header>

      <div className="flex-1 mx-auto w-full max-w-2xl px-4 py-8 md:py-12">
        {step === 0 && !measureMode && (
          <StepContainer title="How do you want to enter your measurements?" subtitle="Choose the method that matches your measurements.">
            <div className="space-y-3">
              <BigChoiceCard theme={theme} onClick={() => { setMeasureMode('actual'); setStep(1); }} title="I have actual measurements" description="You already have final roof dimensions. Just type them in - no pitch calculation needed." icon="check" />
              <BigChoiceCard theme={theme} onClick={() => { setMeasureMode('plan'); setStep(1); }} title="I'm measuring from a plan" description="You have a top-down roof plan. Enter plan dimensions and the roof pitch - we'll calculate the real sloped lengths and areas." icon="plan" />
            </div>
          </StepContainer>
        )}

        {measureMode === 'plan' && step === 1 && (
          <StepContainer title="What is your roof pitch?" subtitle="This is the angle of the roof slope. We use it to calculate the real sloped lengths from your plan measurements." stepLabel={`Step 1 of ${totalSteps}`}>
            <PitchInput theme={theme} masterPitch={masterPitch} masterRatio={masterRatio} unitSystem={u} onUpdateDegrees={updatePitchDegrees} onUpdateRatio={(val) => { setMasterRatio(val); const deg = ratioToDegrees(val); if (deg > 0) setMasterPitch(deg.toFixed(1)); }} />
            <StepNav theme={theme} onBack={() => { window.location.href = '/'; }} onNext={handleNext} nextLabel="Next: Roof Area" />
          </StepContainer>
        )}

        {measureMode && step === roofAreaStep && (
          <ComponentStep theme={theme} kind="roof_area" section={sections['roof_area']} measureMode={measureMode} lenLbl={lenLbl} areaLbl={areaLbl} availableComponents={componentsByKind['roof_area'] || []} pitchDegrees={effectivePitch} unitSystem={u} currencySymbol={cur} total={totals['roof_area']} onAddEntry={(entry) => addEntry('roof_area', entry)} onRemoveEntry={(id) => removeEntry('roof_area', id)} onUpdateWaste={(w) => updateWaste('roof_area', w)} stepNumber={measureMode === 'plan' ? 2 : 1} totalSteps={totalSteps} onBack={() => window.location.href = '/'} onNext={handleNext} nextLabel={COMPONENT_STEPS.length > 0 ? `Next: ${componentLabel(COMPONENT_STEPS[0])}` : 'Generate Report'} capabilities={capabilities} />
        )}

        {measureMode && COMPONENT_STEPS.map((kind, idx) => {
          const stepNum = (measureMode === 'plan' ? 3 : 2) + idx;
          if (step !== stepNum) return null;
          const isLast = idx === COMPONENT_STEPS.length - 1;
          const nextLabel = isLast ? 'Generate Report' : `Next: ${componentLabel(COMPONENT_STEPS[idx + 1])}`;
          return (
            <ComponentStep key={kind} theme={theme} kind={kind} section={sections[kind]} measureMode={measureMode} lenLbl={lenLbl} areaLbl={areaLbl} availableComponents={componentsByKind[kind] || []} pitchDegrees={effectivePitch} unitSystem={u} currencySymbol={cur} total={totals[kind]} roofAreaTotal={kind === 'underlay' || kind === 'fixings' ? (totals['roof_area']?.rawTotal ?? null) : null} onAddEntry={(entry) => addEntry(kind, entry)} onRemoveEntry={(id) => removeEntry(kind, id)} onUpdateWaste={(w) => updateWaste(kind, w)} stepNumber={stepNum} totalSteps={totalSteps} onBack={handleBack} onNext={handleNext} nextLabel={nextLabel} capabilities={capabilities} />
          );
        })}

        {showResults && (
          <ResultsModal sections={allSections} totals={totals} getComponentById={getComponentById} grandTotal={grandTotal} unitSystem={u} allKeys={allKeys} currencySymbol={cur} theme={theme} supplierSlug={theme.supplierSlug} onClose={() => setShowResults(false)} onEdit={() => { setShowResults(false); setStep(measureMode === 'plan' ? 2 : 1); }} />
        )}
      </div>

      <footer className="border-t border-slate-100 py-4">
        <div className="mx-auto max-w-2xl px-4 flex items-center justify-between">
          <span className="text-xs text-slate-400">{theme.copy.footerText}</span>
          {measureMode && !showResults && (
            <button onClick={startOver} className="text-xs text-slate-400 hover:text-slate-600 transition cursor-pointer">Start over</button>
          )}
        </div>
      </footer>
      <style jsx global>{`
        .roof-takeoff-theme h1,
        .roof-takeoff-theme h2,
        .roof-takeoff-theme h3 { font-family: var(--roof-heading-font); }
      `}</style>
    </main>
  );
}
