'use client';

import { useState, useRef } from 'react';
import type { ThemeConfig, ComponentSection, RoofComponentDef } from '@roof-takeoff/core';
import { COMPONENT_DEFS, componentLabel } from '@roof-takeoff/core';

interface SupplierEnquiryModalProps {
  theme: ThemeConfig;
  supplierSlug?: string | null;
  sections: Record<string, ComponentSection>;
  totals: Record<string, { rawTotal: number; withWaste: number; count: number; materialCost: number; labourCost: number; totalCost: number }>;
  getComponentById: (id: string | null) => RoofComponentDef | null;
  grandTotal: number;
  allKeys: string[];
  unitSystem: 'metric' | 'imperial' | 'squares';
  currencySymbol: string;
  onClose: () => void;
}

type Intent = 'detailed_quote' | 'order_request' | 'pricing_question' | 'general_enquiry';

const intentOptions: { value: Intent; label: string; desc: string }[] = [
  { value: 'detailed_quote', label: 'Detailed Quote', desc: 'Ask for a full formal quote' },
  { value: 'order_request', label: 'Order Request', desc: 'I want to order these materials' },
  { value: 'pricing_question', label: 'Pricing Question', desc: 'Ask about pricing or better rates' },
  { value: 'general_enquiry', label: 'General Enquiry', desc: 'Something else' },
];

export function SupplierEnquiryModal({
  theme,
  supplierSlug,
  sections,
  totals,
  getComponentById,
  grandTotal,
  allKeys,
  unitSystem,
  currencySymbol,
  onClose,
}: SupplierEnquiryModalProps) {
  const cur = currencySymbol;
  const lenUnit = unitSystem === 'metric' ? 'm' : 'ft';
  const areaUnit = unitSystem === 'metric' ? 'm\u00B2' : unitSystem === 'imperial' ? 'sq ft' : 'squares';

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [intent, setIntent] = useState<Intent>('detailed_quote');
  const [message, setMessage] = useState('');
  const [includeQuantities, setIncludeQuantities] = useState(true);
  const [includePricing, setIncludePricing] = useState(true);
  const [files, setFiles] = useState<File[]>([]);
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const emailValid = emailRegex.test(email);
  const nameValid = name.trim().length >= 2;
  const canSend = nameValid && emailValid && !sending;

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = Array.from(e.target.files ?? []);
    const allowed = ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'];
    const valid = selected.filter(f => allowed.includes(f.type) && f.size <= 10 * 1024 * 1024);
    const combined = [...files, ...valid].slice(0, 5);
    setFiles(combined);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeFile = (idx: number) => {
    setFiles(files.filter((_, i) => i !== idx));
  };

  const unitFor = (key: string) => {
    const section = sections[key];
    if (key === 'roof_area' || key === 'underlay' || key === 'fixings') return areaUnit;
    if (key.startsWith('custom-') && section?.customDef?.measurementType === 'area') return areaUnit;
    return lenUnit;
  };

  const handleSend = async () => {
    if (!canSend) return;
    setSending(true);
    setError(null);

    try {
      // Upload attachments first (if any)
      const attachmentIds: string[] = [];
      for (const file of files) {
        const formData = new FormData();
        formData.append('file', file);
        const uploadRes = await fetch('/api/free-tools/supplier-enquiry', {
          method: 'PUT',
          body: formData,
        });
        const uploadData = await uploadRes.json();
        if (uploadData.ok && uploadData.fileId) {
          attachmentIds.push(uploadData.fileId);
        } else {
          console.error('[enquiry] File upload failed:', file.name, uploadData.error);
        }
      }

      const takeoffSummary = allKeys.map(key => {
        const section = sections[key];
        const t = totals[key];
        const label = componentLabel(key);
        const isArea = key === 'roof_area' || key === 'underlay' || key === 'fixings';
        const unit = isArea ? areaUnit : lenUnit;
        const entries = (section?.entries || []).map((entry, idx) => {
          const comp = getComponentById(entry.selectedComponentId);
          return {
            label: entry.label || `Entry ${idx + 1}`,
            componentName: comp?.name || 'No product',
            value: entry.computedValue,
            quantity: entry.quantity ?? 1,
          };
        });
        return {
          label,
          unit,
          count: t?.count ?? 0,
          rawTotal: t?.rawTotal ?? 0,
          withWaste: t?.withWaste ?? 0,
          wastePercent: section?.wastePercent ?? 0,
          materialCost: t?.materialCost ?? 0,
          labourCost: t?.labourCost ?? 0,
          totalCost: t?.totalCost ?? 0,
          entries,
        };
      });

      const res = await fetch('/api/free-tools/supplier-enquiry', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          supplierSlug: supplierSlug,
          senderName: name,
          senderEmail: email,
          senderPhone: phone || undefined,
          intent,
          message,
          includeQuantities,
          includePricing,
          includeResultLink: false,
          marketingConsent: false,
          totals: takeoffSummary,
          currency: cur,
          attachmentIds: attachmentIds.length > 0 ? attachmentIds : undefined,
        }),
      });

      const data = await res.json();

      if (data.ok) {
        setSent(true);
      } else {
        setError(data.error || 'Failed to send enquiry. Please try again.');
      }
    } catch {
      setError('An unexpected error occurred. Please try again.');
    } finally {
      setSending(false);
    }
  };

  if (sent) {
    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center backdrop-blur-sm bg-black/40 p-2 md:p-4">
        <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-6 text-center">
          <div className="w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-4" style={{ backgroundColor: `${theme.primary}15` }}>
            <svg className="w-6 h-6" style={{ color: theme.primary }} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
            </svg>
          </div>
          <h3 className="text-lg font-semibold text-slate-900">Enquiry sent!</h3>
          <p className="mt-2 text-sm text-slate-500">
            Your message has been sent to {theme.supplierName}. They will reply directly to your email at {email}.
          </p>
          <button
            onClick={onClose}
            className="mt-5 w-full rounded-lg px-5 py-3 text-sm font-semibold text-white transition"
            style={{ backgroundColor: theme.primary }}
          >
            Done
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center backdrop-blur-sm bg-black/40 p-2 md:p-4 overflow-y-auto">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg my-8 max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="sticky top-0 bg-white border-b border-slate-100 px-5 py-4 flex items-center justify-between z-10">
          <div>
            <h2 className="text-base font-semibold text-slate-900">Send to {theme.supplierName}</h2>
            <p className="text-xs text-slate-400">They will reply directly to your email</p>
          </div>
          <button
            onClick={onClose}
            aria-label="Close"
            className="p-2 text-slate-400 hover:text-slate-600 transition rounded-full hover:bg-slate-50 cursor-pointer min-h-[44px] min-w-[44px] flex items-center justify-center"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        {/* Body */}
        <div className="px-5 py-4 space-y-4">
          {/* Name + Email */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">Your name *</label>
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm focus:outline-none"
                style={{ borderColor: name ? theme.primary : undefined }}
                placeholder="John Smith"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">Your email *</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full rounded-lg border px-3 py-2 text-sm focus:outline-none"
                style={{ borderColor: email ? (emailValid ? theme.primary : '#ef4444') : undefined }}
                placeholder="john@example.com"
              />
              {email && !emailValid && <p className="mt-1 text-xs text-red-500">Please enter a valid email address.</p>}
            </div>
          </div>

          {/* Phone */}
          <div>
            <label className="block text-xs font-medium text-slate-600 mb-1">Phone (optional)</label>
            <input
              type="tel"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm focus:outline-none"
              style={{ borderColor: phone ? theme.primary : undefined }}
              placeholder="+44 7700 900123"
            />
          </div>

          {/* Intent */}
          <div>
            <label className="block text-xs font-medium text-slate-600 mb-1.5">What do you need?</label>
            <div className="grid grid-cols-2 gap-2">
              {intentOptions.map((opt) => (
                <button
                  key={opt.value}
                  onClick={() => setIntent(opt.value)}
                  className="text-left rounded-lg border p-2.5 transition cursor-pointer"
                  style={intent === opt.value
                    ? { borderColor: theme.primary, backgroundColor: `${theme.primary}08` }
                    : { borderColor: '#e2e8f0' }
                  }
                >
                  <div className="text-xs font-semibold text-slate-900">{opt.label}</div>
                  <div className="text-[11px] text-slate-400 mt-0.5">{opt.desc}</div>
                </button>
              ))}
            </div>
          </div>

          {/* Message */}
          <div>
            <label className="block text-xs font-medium text-slate-600 mb-1">Message</label>
            <textarea
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              rows={4}
              maxLength={5000}
              className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm focus:outline-none resize-none"
              style={{ borderColor: message ? theme.primary : undefined }}
              placeholder="Hi, I have estimated my roof takeoff using your calculator. Can you provide a formal quote? I have attached the roof plan..."
            />
            <p className="mt-1 text-[11px] text-slate-400 text-right">{message.length}/5000</p>
          </div>

          {/* Include toggles */}
          <div className="space-y-2 rounded-lg bg-slate-50 p-3">
            <p className="text-xs font-medium text-slate-600">Include in email:</p>
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={includeQuantities} onChange={(e) => setIncludeQuantities(e.target.checked)} className="rounded border-slate-300" style={{ accentColor: theme.primary }} />
              <span className="text-xs text-slate-600">Takeoff quantities (measurements per component)</span>
            </label>
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={includePricing} onChange={(e) => setIncludePricing(e.target.checked)} className="rounded border-slate-300" style={{ accentColor: theme.primary }} />
              <span className="text-xs text-slate-600">Pricing breakdown (material + labour costs)</span>
            </label>
          </div>

          {/* File upload */}
          <div>
            <label className="block text-xs font-medium text-slate-600 mb-1">Attachments (optional, max 5 files, 10MB each)</label>
            <input
              ref={fileInputRef}
              type="file"
              accept=".pdf,.jpg,.jpeg,.png,.webp"
              multiple
              onChange={handleFileSelect}
              className="hidden"
            />
            <button
              onClick={() => fileInputRef.current?.click()}
              disabled={files.length >= 5}
              className="w-full rounded-lg border border-dashed border-slate-300 px-4 py-3 text-xs text-slate-500 hover:bg-slate-50 transition disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer"
            >
              {files.length >= 5 ? 'Maximum 5 files reached' : '+ Add file (PDF, JPG, PNG, WebP)'}
            </button>
            {files.length > 0 && (
              <div className="mt-2 space-y-1">
                {files.map((file, idx) => (
                  <div key={idx} className="flex items-center justify-between rounded-lg bg-slate-50 px-3 py-1.5">
                    <span className="text-xs text-slate-600 truncate flex-1">{file.name}</span>
                    <span className="text-[11px] text-slate-400 ml-2">{(file.size / 1024 / 1024).toFixed(1)}MB</span>
                    <button onClick={() => removeFile(idx)} className="ml-2 text-slate-300 hover:text-red-500 cursor-pointer">
                      <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Error */}
          {error && (
            <div className="rounded-lg bg-red-50 border border-red-200 px-3 py-2 text-xs text-red-600">
              {error}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="sticky bottom-0 bg-white border-t border-slate-100 px-5 py-3 flex items-center justify-between gap-3">
          <button
            onClick={onClose}
            className="px-4 py-2 text-sm font-medium rounded-lg border border-slate-300 hover:bg-slate-50 transition cursor-pointer min-h-[44px]"
          >
            Cancel
          </button>
          <button
            onClick={handleSend}
            disabled={!canSend}
            className="inline-flex items-center gap-1.5 rounded-lg px-5 py-2 text-sm font-semibold text-white transition min-h-[44px] disabled:opacity-50 disabled:cursor-not-allowed"
            style={{ backgroundColor: theme.primary }}
          >
            {sending ? (
              <>
                <div className="inline-block animate-spin rounded-full h-4 w-4 border-2 border-white/30 border-t-white" />
                Sending...
              </>
            ) : (
              <>
                Send to {theme.supplierName}
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}
